import React, { useEffect, useState } from "react";
import { Card, Button, Typography, message, Spin, Form, Input } from "antd";
import { KeyOutlined } from "@ant-design/icons";
import "./Account.css";
import Captcha from "@src/packages/pro-component/schema/Captcha";
import ArraySelect from "@src/packages/pro-component/schema/ArraySelect";
import axios from "axios";
import { apiBaseUrl } from "@src/util/runtimeConfig";

axios.defaults.baseURL = apiBaseUrl;

const { Title, Text } = Typography;

// Types
interface AccountInfo {
  storeName: string;
  email: string;
  createdAt: string;
  logo: string;
  address: string;
  username: string;
  brands?: { id: number; name: string }[];
}

interface CreateAccountForm {
  username: string;
  password: string;
  confirmPassword: string;
  brandIds: number[];
}

interface ResetPasswordForm {
  newPassword: string;
  confirmPassword: string;
}

interface UpdateBrandsForm {
  brandIds: number[];
}

const Account: React.FC = (props: any) => {
  // Hooks
  const [loading, setLoading] = useState<boolean>(true);
  const [hasAccount, setHasAccount] = useState<boolean>(false);
  const [accountInfo, setAccountInfo] = useState<AccountInfo | null>(null);
  const [captchaValue, setCaptchaValue] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [form] = Form.useForm();
  const [isCheckComplete, setIsCheckComplete] = useState<boolean>(false);
  const [resetPasswordForm] = Form.useForm();
  const [showResetForm, setShowResetForm] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [resetCaptchaValue, setResetCaptchaValue] = useState<string>("");
  const [selectedBrandIds, setSelectedBrandIds] = useState<number[]>([]);
  const [showUpdateBrandsForm, setShowUpdateBrandsForm] = useState(false);
  const [updateBrandsForm] = Form.useForm();
  const [isUpdatingBrands, setIsUpdatingBrands] = useState(false);
  const [updateBrandsCaptchaValue, setUpdateBrandsCaptchaValue] =
    useState<string>("");
  const [selectedUpdateBrandIds, setSelectedUpdateBrandIds] = useState<
    number[]
  >([]);

  const token = localStorage.getItem("token");
  const storeId = Number(props.query.id);

  // API Calls
  const checkAccountStatus = async () => {
    try {
      const response = await axios.post(
        "/admin/seller/check-account-exist",
        {
          storeId,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      const data = response.data.data;
      console.log("data shop", data);
      setHasAccount(data.exist);
      if (data.exist) {
        setAccountInfo(data.accountInfo);
        // Set current brands for update form
        if (data.accountInfo?.brands) {
          const brandIds = data.accountInfo.brands.map(
            (brand: any) => brand.id
          );
          setSelectedUpdateBrandIds(brandIds);
        }
      }
      setIsCheckComplete(true);
    } catch (error) {
      message.error("Không thể kiểm tra trạng thái tài khoản");
      setIsCheckComplete(false);
    } finally {
      setLoading(false);
    }
  };

  const handleResetPassword = async (values: ResetPasswordForm) => {
    if (!resetCaptchaValue) {
      message.error("Vui lòng nhập mã captcha");
      return;
    }

    setIsResetting(true);
    try {
      const captcha = resetCaptchaValue.split(",");
      const response = await axios.post(
        "/admin/seller/reset-password",
        {
          newPassword: values.newPassword,
          confirmPassword: values.confirmPassword,
          captchaText: captcha[1],
          tokenCapcha: captcha[0],
          storeId,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      if (response.data.code === 0) {
        message.success("Đặt lại mật khẩu thành công");
        setShowResetForm(false);
        resetPasswordForm.resetFields();
      } else {
        throw new Error(response.data.message);
      }
    } catch (error: any) {
      const errorMessage =
        error.response?.data?.message ||
        error.message ||
        "Đặt lại mật khẩu thất bại";
      message.error(errorMessage);
    } finally {
      setIsResetting(false);
    }
  };

  const handleCreateAccount = async (values: CreateAccountForm) => {
    if (!captchaValue) {
      message.error("Vui lòng nhập mã captcha");
      return;
    }

    setIsSubmitting(true);
    try {
      const captcha = captchaValue.split(",");
      const response = await axios.post(
        "/admin/seller/create-account",
        {
          username: values.username,
          password: values.password,
          confirmPassword: values.confirmPassword,
          brandIds: selectedBrandIds,
          captchaText: captcha[1],
          tokenCapcha: captcha[0],
          storeId,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      if (response.data.code === 0) {
        message.success("Tạo tài khoản thành công");
        await checkAccountStatus();
      } else {
        throw new Error(response.data.message);
      }
    } catch (error: any) {
      const errorMessage =
        error.response?.data?.message ||
        error.message ||
        "Tạo tài khoản thất bại";
      message.error(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleUpdateBrands = async (values: UpdateBrandsForm) => {
    if (!updateBrandsCaptchaValue) {
      message.error("Vui lòng nhập mã captcha");
      return;
    }

    setIsUpdatingBrands(true);
    try {
      const captcha = updateBrandsCaptchaValue.split(",");
      const response = await axios.post(
        "/admin/brand/update-brands-of-store",
        {
          brandIds: selectedUpdateBrandIds,
          captchaText: captcha[1],
          tokenCapcha: captcha[0],
          storeId,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      if (response.data.code === 0) {
        message.success("Cập nhật thương hiệu thành công");
        setShowUpdateBrandsForm(false);
        updateBrandsForm.resetFields();
        await checkAccountStatus(); // Refresh account info
      } else {
        throw new Error(response.data.message);
      }
    } catch (error: any) {
      const errorMessage =
        error.response?.data?.message ||
        error.message ||
        "Cập nhật thương hiệu thất bại";
      message.error(errorMessage);
    } finally {
      setIsUpdatingBrands(false);
    }
  };

  // Effects
  useEffect(() => {
    checkAccountStatus();
  }, []);

  // Schema cho ArraySelect để gọi API find_brand
  const brandSchema = {
    pageId: 311, // Sử dụng pageId phù hợp với hệ thống của bạn
    api: "find_brand",
    embed: [],
  };

  // Render helpers
  const renderCreateAccountForm = () => (
    <div className="create-account-form">
      <Title level={3}>Tạo tài khoản người bán</Title>
      <Form
        form={form}
        layout="vertical"
        onFinish={handleCreateAccount}
        className="form"
      >
        <Form.Item
          label="Tên đăng nhập"
          name="username"
          rules={[{ required: true, message: "Vui lòng nhập tên đăng nhập" }]}
        >
          <Input />
        </Form.Item>

        <Form.Item
          label="Mật khẩu"
          name="password"
          rules={[
            { required: true, message: "Vui lòng nhập mật khẩu" },
            {
              pattern: /^(?=.*[A-Za-z])(?=.*\d).{8,}$/,
              message:
                "Mật khẩu phải có ít nhất 8 ký tự và chứa cả chữ và số",
            },
          ]}
        >
          <Input.Password />
        </Form.Item>

        <Form.Item
          label="Xác nhận mật khẩu"
          name="confirmPassword"
          dependencies={["password"]}
          rules={[
            { required: true, message: "Vui lòng xác nhận mật khẩu" },
            ({ getFieldValue }) => ({
              validator(_, value) {
                if (!value || getFieldValue("password") === value) {
                  return Promise.resolve();
                }
                return Promise.reject(new Error("Mật khẩu không khớp"));
              },
            }),
          ]}
        >
          <Input.Password />
        </Form.Item>

        <Form.Item
          label="Chọn thương hiệu"
          name="brandIds"
          rules={[
            { required: true, message: "Vui lòng chọn ít nhất một thương hiệu" },
          ]}
        >
          <ArraySelect
            schema={brandSchema}
            type="checkbox"
            placeholder="Chọn các thương hiệu..."
            value={selectedBrandIds}
            onChange={(value) => {
              console.log("Brand IDs selected:", value);
              setSelectedBrandIds(value);
              form.setFieldsValue({ brandIds: value });
            }}
          />
        </Form.Item>

        <Form.Item label="Mã xác thực">
          <Captcha onChange={(value) => setCaptchaValue(value)} />
        </Form.Item>

        <Form.Item>
          <Button
            type="primary"
            htmlType="submit"
            loading={isSubmitting}
            className="submit-btn"
            block
          >
            Tạo tài khoản
          </Button>
        </Form.Item>
      </Form>
    </div>
  );

  const renderResetPasswordForm = () => (
    <div className="reset-password-form">
      <Title level={4}>Đặt lại mật khẩu</Title>
      <Form
        form={resetPasswordForm}
        layout="vertical"
        onFinish={handleResetPassword}
        className="form"
      >
        <Form.Item
          label="Mật khẩu mới"
          name="newPassword"
          rules={[
            { required: true, message: "Vui lòng nhập mật khẩu" },
            {
              pattern: /^(?=.*[A-Za-z])(?=.*\d).{8,}$/,
              message:
                "Mật khẩu phải có ít nhất 8 ký tự và chứa cả chữ và số",
            },
          ]}
        >
          <Input.Password />
        </Form.Item>

        <Form.Item
          label="Xác nhận mật khẩu mới"
          name="confirmPassword"
          dependencies={["newPassword"]}
          rules={[
            { required: true, message: "Vui lòng xác nhận mật khẩu mới" },
            ({ getFieldValue }) => ({
              validator(_, value) {
                if (!value || getFieldValue("newPassword") === value) {
                  return Promise.resolve();
                }
                return Promise.reject(new Error("Mật khẩu không khớp"));
              },
            }),
          ]}
        >
          <Input.Password />
        </Form.Item>

        <Form.Item label="Mã xác thực">
          <Captcha onChange={(value) => setResetCaptchaValue(value)} />
        </Form.Item>

        <Form.Item>
          <Button
            type="primary"
            htmlType="submit"
            loading={isResetting}
            className="submit-btn"
            block
          >
            Đặt lại mật khẩu
          </Button>
          <Button
            onClick={() => setShowResetForm(false)}
            className="cancel-btn"
            block
            style={{ marginTop: 8 }}
          >
            Hủy
          </Button>
        </Form.Item>
      </Form>
    </div>
  );

  const renderUpdateBrandsForm = () => (
    <div className="update-brands-form">
      <Title level={4}>Cập nhật thương hiệu</Title>
      <Form
        form={updateBrandsForm}
        layout="vertical"
        onFinish={handleUpdateBrands}
        className="form"
        initialValues={{ brandIds: selectedUpdateBrandIds }}
      >
        <Form.Item
          label="Chọn thương hiệu"
          name="brandIds"
          rules={[
            { required: true, message: "Vui lòng chọn ít nhất một thương hiệu" },
          ]}
        >
          <ArraySelect
            schema={brandSchema}
            type="checkbox"
            placeholder="Chọn các thương hiệu..."
            value={selectedUpdateBrandIds}
            onChange={(value) => {
              console.log("Update Brand IDs selected:", value);
              setSelectedUpdateBrandIds(value);
              updateBrandsForm.setFieldsValue({ brandIds: value });
            }}
          />
        </Form.Item>

        <Form.Item label="Mã xác thực">
          <Captcha onChange={(value) => setUpdateBrandsCaptchaValue(value)} />
        </Form.Item>

        <Form.Item>
          <Button
            type="primary"
            htmlType="submit"
            loading={isUpdatingBrands}
            className="submit-btn"
            block
          >
            Cập nhật thương hiệu
          </Button>
          <Button
            onClick={() => setShowUpdateBrandsForm(false)}
            className="cancel-btn"
            block
            style={{ marginTop: 8 }}
          >
            Hủy
          </Button>
        </Form.Item>
      </Form>
    </div>
  );

  const renderAccountInfo = () => (
    <div className="account-info">
      <Title level={3}>Thông tin tài khoản người bán</Title>
      {accountInfo?.logo && (
        <div className="info-item logo-container">
          <img src={accountInfo.logo} alt="Store Logo" className="store-logo" />
        </div>
      )}
      <div className="info-item">
        <Text strong>Tên đăng nhập:</Text>
        <Text>{accountInfo?.username}</Text>
      </div>
      <div className="info-item">
        <Text strong>Tên cửa hàng:</Text>
        <Text>{accountInfo?.storeName}</Text>
      </div>
      <div className="info-item">
        <Text strong>Email:</Text>
        <Text>{accountInfo?.email}</Text>
      </div>
      <div className="info-item">
        <Text strong>Địa chỉ:</Text>
        <Text>{accountInfo?.address}</Text>
      </div>
      <div className="info-item">
        <Text strong>Ngày tạo:</Text>
        <Text>{accountInfo?.createdAt}</Text>
      </div>
      {accountInfo?.brands && accountInfo.brands.length > 0 && (
        <div className="info-item">
          <Text strong>Thương hiệu:</Text>
          <div>
            {accountInfo.brands.map((brand, index) => (
              <Text key={brand.id}>
                {brand.name}
                {index < accountInfo.brands!.length - 1 ? ", " : ""}
              </Text>
            ))}
          </div>
        </div>
      )}
      {!showResetForm && !showUpdateBrandsForm && (
        <div style={{ display: "flex", gap: "8px", flexDirection: "column" }}>
          <Button
            type="primary"
            icon={<KeyOutlined />}
            onClick={() => setShowResetForm(true)}
            className="reset-password-btn"
          >
            Đặt lại mật khẩu
          </Button>
          <Button
            type="default"
            onClick={() => setShowUpdateBrandsForm(true)}
            className="update-brands-btn"
          >
            Cập nhật thương hiệu
          </Button>
        </div>
      )}
      {showResetForm && renderResetPasswordForm()}
      {showUpdateBrandsForm && renderUpdateBrandsForm()}
    </div>
  );

  if (loading) {
    return (
      <div className="account-container">
        <Spin size="large" />
      </div>
    );
  }

  if (!isCheckComplete) {
    return (
      <div className="account-container">
        <Card className="account-card">
          <Text>
            Không thể tải thông tin tài khoản. Vui lòng thử lại sau.
          </Text>
        </Card>
      </div>
    );
  }

  return (
    <div className="account-container">
      <Card className="account-card">
        {!hasAccount ? renderCreateAccountForm() : renderAccountInfo()}
      </Card>
    </div>
  );
};

export default Account;
