interface OrderTableProps {
  pageId: number;
  filters: any;
  buildQueryParams: () => any;
  updatePagination: (current: number, pageSize: number) => void;
  onStatusCountsUpdate?: (counts: any) => void;
  authUser?: any;
}

const OrderTable: React.FC<OrderTableProps> = ({
  pageId,
  filters,
  buildQueryParams,
  updatePagination,
  onStatusCountsUpdate,
  authUser,
}) => {
  const [loading, setLoading] = useState(false);
  const [orders, setOrders] = useState<Order[]>([]);
  const [total, setTotal] = useState(0);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [detailVisible, setDetailVisible] = useState(false);
  const [cancelReason, setCancelReason] = useState("");
  const [chatDrawerVisible, setChatDrawerVisible] = useState(false);
  const [chatDialogVisible, setChatDialogVisible] = useState(false);
  const [selectedUser, setSelectedUser] = useState<any>(null);
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [selectedUserInfo, setSelectedUserInfo] = useState<UserInfo>();
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [customerMap, setCustomerMap] = useState<
    Record<number | string, string>
  >({});
  const [customerPhoneMap, setCustomerPhoneMap] = useState<
    Record<number | string, string>
  >({});

  const fetchOrders = useCallback(
    async (params: any) => {
      try {
        setLoading(true);
        const pageInfo = await helper.getPage(pageId);

        const response = await helper.callPageApi(
          pageInfo,
          "get-orders-ship",
          params,
        );

        if (response?.data) {
          const rawOrders: Order[] = Array.isArray(response.data.data)
            ? response.data.data
            : [];
          setTotal(
            typeof response.data.count === "number" ? response.data.count : 0,
          );

          if (response.data.statusCounts && onStatusCountsUpdate) {
            onStatusCountsUpdate(response.data.statusCounts);
          }

          const customerIds = Array.from(
            new Set(
              rawOrders
                .map((order: Order) => order.customerId)
                .filter((id) => id !== undefined && id !== null && id !== ""),
            ),
          );

          const newCustomerMap: Record<number | string, string> = {};
          const newCustomerPhoneMap: Record<number | string, string> = {};
          if (customerIds.length > 0) {
            try {
              const customerResponse: any = await helper.callPageApi(
                pageInfo,
                "find-customer",
                {
                  queryInput: JSON.stringify({ id: customerIds }),
                  limit: Math.max(customerIds.length, 100),
                },
              );

              const customerList = Array.isArray(customerResponse?.data?.data)
                ? customerResponse.data.data
                : Array.isArray(customerResponse?.data)
                ? customerResponse.data
                : [];

              customerList.forEach((item: any) => {
                const id = item?.id ?? item?._id ?? item?.customerId;
                const name = item?.name || "";
                const phone = item?.phone || "";
                if (id !== undefined && id !== null) {
                  newCustomerMap[id] = name;
                  newCustomerPhoneMap[id] = phone;
                }
              });
            } catch (err) {
              console.error("Error fetching customers:", err);
            }
          }

          setCustomerMap(newCustomerMap);
          setCustomerPhoneMap(newCustomerPhoneMap);
          setOrders(
            rawOrders.map((order) => ({
              ...order,
              customerName: newCustomerMap[order.customerId] || "",
              customerPhone:
                newCustomerPhoneMap[order.customerId] ||
                order.receivePhone ||
                "",
            })),
          );
        }
      } catch (error) {
        console.error("Error fetching orders:", error);
        message.error("Lỗi khi tải danh sách đơn hàng");
      } finally {
        setLoading(false);
      }
    },
    [pageId, onStatusCountsUpdate],
  );

  const handleConfirmOrder = async (
    id: number,
    status: "confirm" | "cancel",
    cancelReason?: string,
  ) => {
    try {
      const pageInfo = await helper.getPage(pageId);
      const response: any = await helper.callPageApi(
        pageInfo,
        "confirm-order",
        {
          orderShipId: id,
          status,
          cancelReason,
        },
      );
      console.log(response, "response");

      if (response?.data?.code === 0) {
        message.success(
          status === "confirm"
            ? "Xác nhận đơn hàng thành công"
            : "Hủy đơn hàng thành công",
        );
        // Refresh data
        fetchOrders(buildQueryParams());
      } else {
        message.error(
          response?.data?.err?.message ||
            response?.data?.message ||
            "Đã có lỗi xảy ra",
        );
      }
    } catch (error: any) {
      console.error("Error confirming order:", error);
      message.error(error?.message || "Đã có lỗi xảy ra");
    }
  };

  const showConfirmModal = (order: Order, action: "confirm" | "cancel") => {
    const title = action === "confirm" ? "Xác nhận đơn hàng" : "Hủy đơn hàng";
    const content =
      action === "confirm"
        ? "Bạn có chắc chắn muốn xác nhận đơn hàng này?"
        : "Bạn có chắc chắn muốn hủy đơn hàng này?";

    if (action === "cancel") {
      Modal.confirm({
        title,
        icon: <ExclamationCircleOutlined />,
        content: (
          <div>
            <p>{content}</p>
            <Input.TextArea
              placeholder="Nhập lý do hủy"
              onChange={(e) => setCancelReason(e.target.value)}
              rows={3}
            />
          </div>
        ),
        okText: "Xác nhận",
        cancelText: "Hủy",
        onOk: () => handleConfirmOrder(order.id, "cancel", cancelReason),
      });
    } else {
      Modal.confirm({
        title,
        icon: <ExclamationCircleOutlined />,
        content,
        okText: "Xác nhận",
        cancelText: "Hủy",
        onOk: () => handleConfirmOrder(order.id, "confirm"),
      });
    }
  };

  useEffect(() => {
    const params = buildQueryParams();
    fetchOrders(params);
  }, [filters, buildQueryParams]);

  const handleTableChange = (pagination: any) => {
    updatePagination(pagination.current, pagination.pageSize);
  };

  const showOrderDetail = (order: Order) => {
    setSelectedOrder(order);
    setDetailVisible(true);
  };

  const getStatusText = (status: string) => {
    const statusMap: Record<string, string> = {
      processing: "Chờ thanh toán",
      wait_for_confirmation: "Chờ xác nhận",
      wait_for_pickup: "Chờ lấy hàng",
      confirmed: "Đã xác nhận",
      shipping: "Đang giao",
      completed: "Hoàn thành",
      canceled: "Đã hủy",
      refund: "Yêu cầu trả hàng",
      refunded: "Đã hoàn tiền",
    };
    return statusMap[status] || status;
  };

  const handleOpenChatDrawer = () => {
    setChatDrawerVisible(!chatDrawerVisible);
  };

  const createConversation = async (customerId: number) => {
    try {
      const response = await axios.post(
        "/admin/chat/create-conversation",
        { customerId },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        },
      );

      if (response.data.code === 0) {
        const conversationData = response.data.data;

        // Cập nhật state với thông tin từ API
        setSelectedUserInfo(conversationData.userInfo);
        setSelectedConversation(conversationData);

        // Mở chat dialog
        setChatDialogVisible(true);
      } else {
        message.error("Không thể tạo cuộc hội thoại");
      }
    } catch (error) {
      console.error("Lỗi khi tạo cuộc hội thoại:", error);
      message.error("Đã có lỗi xảy ra khi tạo cuộc hội thoại");
    }
  };

  const handleOpenChat = async (customerId: any) => {
    await createConversation(customerId.id);
  };

  const handleCloseChat = () => {
    setChatDialogVisible(false);
    setSelectedUser(null);
  };

  const handleCloseDrawer = () => {
    setChatDrawerVisible(false);
  };

  const handleSendMessage = (content: string, imageUrl?: string | null) => {
    // Tạo message mới
    const newMessage: Message = {
      id: Date.now().toString(), // Tạm thời dùng timestamp làm id
      content: content,
      isMine: true, // Tin nhắn của shop
      timestamp: new Date(),
      type: "text",
    };

    // Thêm vào danh sách tin nhắn
    setChatMessages((prev) => [...prev, newMessage]);

    // Log để debug
    console.log("Sending message:", {
      content,
      imageUrl,
      to: selectedUser?.id,
    });
  };

  const handleChatSelect = (
    conversationId: string,
    userInfo: UserInfo,
    conversation: Conversation,
  ) => {
    setSelectedUserInfo(userInfo);
    setSelectedConversation(conversation);
    setChatDialogVisible(true);
  };

  const columns = [
    {
      title: "Ngày đặt hàng",
      dataIndex: "createdAt",
      key: "createdAt",
      align: "center" as const,
      render: (date: string) => (
        <div data-label="Ngày đặt hàng">{formatDateTime(date)}</div>
      ),
    },
    {
      title: "Khách hàng",
      key: "customer",
      align: "center" as const,
      render: (_: unknown, record: Order) => (
        <div data-label="Khách hàng">
          {record.customerName || customerMap[record.customerId] || "-"}
        </div>
      ),
    },
    {
      title: "Số điện thoại",
      key: "customerPhone",
      align: "center" as const,
      render: (_: unknown, record: Order) => (
        <div data-label="Số điện thoại">
          {record.customerPhone ||
            customerPhoneMap[record.customerId] ||
            record.receivePhone ||
            "-"}
        </div>
      ),
    },
    {
      title: "Sản phẩm",
      key: "product",
      render: (_: unknown, record: Order) => (
        <div data-label="Sản phẩm">
          <UserInfo>
            <Avatar size="small" icon={<UserOutlined />} />
            <Text>{record.receiveName}</Text>
            {authUser && authUser.roleSpecial === "SHOP" && (
              <MessageOutlined
                style={{ color: "#67AE3E", cursor: "pointer" }}
                onClick={(e) => {
                  e.stopPropagation();
                  handleOpenChat({
                    id: record.customerId,
                    name: record.receiveName,
                  });
                }}
              />
            )}
            <OrderCode>Mã đơn hàng: {record.id}</OrderCode>
          </UserInfo>
          {record.orderItemInfos.map((item, index) => (
            <ProductInfo key={index}>
              <ProductImage src={item.images[0]} />
              <ProductDetails>
                <ProductName>{item.name}</ProductName>
                <ProductVariation>
                  {item.attributeValues
                    ? `Phân loại: ${item.attributeValues}, x${
                        item.quantity || 1
                      }`
                    : `x${item.quantity || 1}`}
                </ProductVariation>
              </ProductDetails>
            </ProductInfo>
          ))}
        </div>
      ),
    },

    {
      title: "Tổng đơn hàng",
      dataIndex: "totalMoney",
      key: "totalMoney",
      align: "center" as const,
      render: (amount: number, record: Order) => {
        const totalQuantity = (record.orderItemInfos || []).reduce(
          (sum, item) => sum + (Number(item?.quantity) || 1),
          0,
        );
        return (
          <div data-label="Tổng đơn hàng">
            <div>x{totalQuantity || 1}</div>
            <div>{formatMoney(amount)}</div>
          </div>
        );
      },
    },
    {
      title: "Trạng thái",
      key: "status",
      align: "center" as const,
      render: (_: unknown, record: Order) => (
        <div>
          <StatusTag $status={record.status}>
            {getStatusText(record.status)}
          </StatusTag>
          {record.status === "canceled" && (
            <Tooltip title={`Lý do hủy: ${record.cancelReason}`}>
              <QuestionCircleOutlined
                style={{ marginLeft: 4, color: "#8c8c8c" }}
              />
            </Tooltip>
          )}
        </div>
      ),
    },
    // {
    //   title: "Đơn vị vận chuyển",
    //   key: "delivery",
    //   align: "center" as const,
    //   width: 150,
    //   render: (_: unknown, record: Order) => (
    //     <DeliveryInfo>
    //       {record.shipCarrier && (
    //         <ShipCarrier>{record.shipCarrier}</ShipCarrier>
    //       )}
    //       {record.shipServiceName && (
    //         <ShipService>{record.shipServiceName}</ShipService>
    //       )}
    //       {record.shipOrderCodeId && (
    //         <ShipOrderCode>{record.shipOrderCodeId}</ShipOrderCode>
    //       )}
    //     </DeliveryInfo>
    //   ),
    // },
    // {
    //   title: "Thao tác",
    //   key: "action",
    //   align: "center" as const,
    //   render: (_: unknown, record: Order) => (
    //     <ActionSpace>
    //       <Button
    //         type="link"
    //         style={{ color: "#1890ff" }}
    //         onClick={() => showOrderDetail(record)}
    //       >
    //         Chi tiết
    //       </Button>
    //       {/* {record.status === "wait_for_confirmation" && (
    //         <>
    //           <ActionButton
    //             type="primary"
    //             onClick={() => showConfirmModal(record, "confirm")}
    //           >
    //             Xác nhận
    //           </ActionButton>
    //           <ActionButton
    //             danger
    //             onClick={() => showConfirmModal(record, "cancel")}
    //           >
    //             Hủy
    //           </ActionButton>
    //         </>
    //       )}
    //       {record.status === "confirmed" && (
    //         <ActionButton
    //           danger
    //           onClick={() => showConfirmModal(record, "cancel")}
    //         >
    //           Hủy
    //         </ActionButton>
    //       )} */}
    //     </ActionSpace>
    //   ),
    // },
  ];

  return (
    <>
      <TableContainer>
        <OrderCountText>{total} Đơn hàng</OrderCountText>

        <Table
          columns={columns}
          dataSource={orders}
          loading={loading}
          rowKey="id"
          pagination={{
            total,
            showSizeChanger: true,
            showTotal: (total) => `Tổng số ${total} đơn hàng`,
            responsive: true,
            position: ["bottomCenter"],
            size: window.innerWidth <= 576 ? "small" : "default",
          }}
          onChange={handleTableChange}
          scroll={{ x: "max-content" }}
        />
      </TableContainer>

      <OrderDetail
        visible={detailVisible}
        order={selectedOrder}
        onClose={() => {
          setDetailVisible(false);
          setSelectedOrder(null);
        }}
      />

      {authUser && authUser.roleSpecial === "SHOP" && (
        <>
          <ChatDrawer
            visible={chatDrawerVisible}
            onClose={handleCloseDrawer}
            onChatSelect={handleChatSelect}
          />

          <ChatDialog
            visible={chatDialogVisible}
            onClose={handleCloseChat}
            userInfo={selectedUserInfo}
            conversation={selectedConversation}
            messages={chatMessages}
            onSendMessage={handleSendMessage}
          />

          <ChatButton
            type="primary"
            icon={<MessageOutlined />}
            onClick={handleOpenChatDrawer}
            title="Chat"
          />
        </>
      )}
    </>
  );
};

const mapStateToProps = ({ auth }: any) => ({
  authUser: auth.authUser,
});

export default connect(mapStateToProps)(OrderTable);
