import React, { useEffect, useMemo, useRef, useState } from "react";
import { Alert, Button, Input, Modal, Space, Table } from "antd";
import { SearchOutlined } from "@ant-design/icons";
import { helper } from "@src/controls/controlHelper";

const PAGE_SIZE = 10;
type CustomerField = "id" | "name" | "phone" | "email";
type CustomerFilters = Record<CustomerField, string>;

export interface CustomerItem {
  id: number;
  name: string | null;
  phone: string | null;
  email: string | null;
}

interface Props {
  pageInfo?: any;
  visible: boolean;
  selectedCustomer: CustomerItem | null;
  resetKey?: number;
  onSelect: (customer: CustomerItem) => void;
  onCancel: () => void;
}

const emptyFilters = (): CustomerFilters => ({
  id: "",
  name: "",
  phone: "",
  email: "",
});

export default function CustomerPicker({
  pageInfo,
  visible,
  selectedCustomer,
  resetKey,
  onSelect,
  onCancel,
}: Props) {
  const searchInputRefs = useRef<Partial<Record<CustomerField, Input>>>({});
  const [customers, setCustomers] = useState<CustomerItem[]>([]);
  const [customerCount, setCustomerCount] = useState(0);
  const [page, setPage] = useState(1);
  const [filters, setFilters] = useState<CustomerFilters>(emptyFilters);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    setFilters(emptyFilters());
    setPage(1);
  }, [resetKey]);

  const customerApi = useMemo(
    () =>
      (pageInfo?.apis || []).find((item: any) => {
        const path = String(item.url || "")
          .split("?")[0]
          .replace(/\/+$/, "");
        return (
          String(item.method || "").toUpperCase() === "GET" &&
          (path === "/api/customer" || path === "/customer")
        );
      }),
    [pageInfo]
  );

  useEffect(() => {
    if (!visible) return;
    if (!customerApi) {
      setError("Trang chưa cấu hình API GET /api/customer.");
      setCustomers([]);
      setCustomerCount(0);
      return;
    }

    const idFilter = filters.id.trim();
    if (idFilter && (!/^\d+$/.test(idFilter) || Number(idFilter) <= 0)) {
      setError("ID khách hàng phải là số nguyên dương.");
      setCustomers([]);
      setCustomerCount(0);
      return;
    }

    let cancelled = false;
    const loadCustomers = async () => {
      setLoading(true);
      setError("");
      try {
        const queryInput: Record<string, any> = {};
        if (idFilter) queryInput.id = Number(idFilter);
        for (const field of ["name", "phone", "email"] as const) {
          const value = filters[field].trim();
          if (value) queryInput[field] = { contains: value };
        }
        const response: any = await helper.callPageApi(
          pageInfo,
          customerApi.name,
          {
            queryInput: JSON.stringify(queryInput),
            select: "id,name,phone,email",
            skip: (page - 1) * PAGE_SIZE,
            limit: PAGE_SIZE,
            sort: JSON.stringify([{ id: "desc" }]),
          }
        );
        if (cancelled) return;
        if (response?.status !== 200 || !Array.isArray(response?.data?.data)) {
          throw new Error(
            response?.data?.message || "Không thể tải danh sách khách hàng."
          );
        }
        setCustomers(response.data.data);
        setCustomerCount(Number(response.data.count) || 0);
      } catch (cause: any) {
        if (cancelled) return;
        setCustomers([]);
        setCustomerCount(0);
        setError(cause?.message || "Không thể tải danh sách khách hàng.");
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    loadCustomers();
    return () => {
      cancelled = true;
    };
  }, [customerApi, filters, page, pageInfo, visible]);

  const columnSearch = (field: CustomerField, title: string) => ({
    filteredValue: filters[field] ? [filters[field]] : null,
    onFilterDropdownVisibleChange: (opened: boolean) => {
      if (opened) {
        window.setTimeout(() => searchInputRefs.current[field]?.focus(), 0);
      }
    },
    filterIcon: (filtered: boolean) => (
      <SearchOutlined style={{ color: filtered ? "#68af38" : undefined }} />
    ),
    filterDropdown: ({
      selectedKeys,
      setSelectedKeys,
      confirm,
      clearFilters,
    }: any) => (
      <div style={{ padding: 8, width: 240 }}>
        <Input
          ref={(input) => {
            searchInputRefs.current[field] = input || undefined;
          }}
          autoFocus
          type={field === "id" ? "number" : "text"}
          placeholder={`Tìm kiếm ${title.toLowerCase()}`}
          value={selectedKeys[0] || ""}
          onChange={(event) =>
            setSelectedKeys(event.target.value ? [event.target.value] : [])
          }
          onPressEnter={() => confirm()}
          style={{ marginBottom: 8 }}
        />
        <Space>
          <Button
            type="primary"
            size="small"
            icon={<SearchOutlined />}
            onClick={() => confirm()}
          >
            Tìm kiếm
          </Button>
          <Button
            size="small"
            onClick={() => {
              clearFilters?.();
              confirm();
            }}
          >
            Đặt lại
          </Button>
        </Space>
      </div>
    ),
  });

  const columns: any[] = [
    {
      title: "ID",
      dataIndex: "id",
      key: "id",
      width: 100,
      ...columnSearch("id", "ID"),
    },
    {
      title: "Tên",
      dataIndex: "name",
      key: "name",
      width: 210,
      render: (value: string | null) => value || "—",
      ...columnSearch("name", "tên"),
    },
    {
      title: "Số điện thoại",
      dataIndex: "phone",
      key: "phone",
      width: 170,
      render: (value: string | null) => value || "—",
      ...columnSearch("phone", "số điện thoại"),
    },
    {
      title: "Email",
      dataIndex: "email",
      key: "email",
      width: 250,
      render: (value: string | null) => value || "—",
      ...columnSearch("email", "email"),
    },
  ];

  return (
    <Modal
      title="Chọn khách hàng"
      visible={visible}
      centered
      width={960}
      style={{ maxWidth: "calc(100vw - 32px)" }}
      bodyStyle={{ maxHeight: "calc(100vh - 180px)", overflowY: "auto" }}
      footer={null}
      onCancel={onCancel}
    >
      {error && (
        <Alert
          type="error"
          showIcon
          message={error}
          style={{ marginBottom: 16 }}
          role="alert"
        />
      )}
      <Table<CustomerItem>
        rowKey="id"
        size="middle"
        loading={loading}
        dataSource={customers}
        columns={columns}
        scroll={{ x: 760 }}
        locale={{
          emptyText: error ? "Không thể tải dữ liệu" : "Không có khách hàng",
        }}
        rowSelection={{
          type: "radio",
          selectedRowKeys: selectedCustomer ? [selectedCustomer.id] : [],
          onSelect: onSelect,
        }}
        onRow={(record) => ({ onClick: () => onSelect(record) })}
        pagination={{
          current: page,
          pageSize: PAGE_SIZE,
          total: customerCount,
          showSizeChanger: false,
          showTotal: (total, range) =>
            `${range[0]}–${range[1]} trên ${total} khách hàng`,
        }}
        onChange={(pagination, tableFilters) => {
          const nextFilters = emptyFilters();
          for (const field of Object.keys(nextFilters) as CustomerField[]) {
            nextFilters[field] = String(tableFilters[field]?.[0] || "");
          }
          const filtersChanged = (
            Object.keys(nextFilters) as CustomerField[]
          ).some((field) => nextFilters[field] !== filters[field]);
          setFilters(nextFilters);
          setPage(filtersChanged ? 1 : pagination.current || 1);
        }}
      />
    </Modal>
  );
}
