import React, { useEffect, useRef, useState } from "react";
import {
  Alert,
  Button,
  Card,
  Col,
  DatePicker,
  Form,
  Input,
  InputNumber,
  Modal,
  Radio,
  Row,
  Space,
  Statistic,
  Typography,
} from "antd";
import {
  MinusOutlined,
  PlayCircleOutlined,
  PlusOutlined,
  ReloadOutlined,
} from "@ant-design/icons";
import moment from "moment";
import { v4 as uuid } from "uuid";
import ProTable from "@src/packages/pro-table/Table";
import request from "@src/util/request";
import CustomerPicker, { CustomerItem } from "./CustomerPicker";

const HISTORY_PAGE_SIZE = 20;
const businessDate = () =>
  new Date(Date.now() + 7 * 60 * 60 * 1000).toISOString().slice(0, 10);

interface EntitlementFormValues {
  amount: number;
}

interface EntitlementResponse {
  code: number;
  message: string;
  data?: {
    id: string;
    totalEntitlementAmount: number;
    totalAccumulatedAmount: number;
  };
}

interface ReceivedBalanceResponse {
  code: number;
  message: string;
  data?: {
    customerId: number;
    totalEntitlementAmount: number;
    totalAccumulatedAmount: number;
    remainingAmount: number;
  };
}

interface ReceivedAdjustmentResponse extends ReceivedBalanceResponse {}

interface PoolResponse {
  code: number;
  message: string;
  data?: {
    id: string;
    calculationDate: string;
    totalManualPoolAmount: number;
  };
}

interface PoolBalanceResponse {
  code: number;
  message: string;
  data?: {
    calculationDate: string;
    runStatus: string | null;
    manualPoolAmount: number;
    settledPoolAmount: number | null;
  };
}

interface DistributionItem {
  customerId: number;
  name: string | null;
  username: string | null;
  phone: string | null;
  email: string | null;
  distributedAmount: number;
  totalEntitlementAmount: number;
  remainingAmount: number;
}

interface DistributionsResponse {
  code: number;
  message: string;
  data?: {
    runStatus: string | null;
    runError: string | null;
    total: number;
    filteredTotal: number;
    totalDistributedAmount: number;
    items: DistributionItem[];
  };
}

interface RunResponse {
  code: number;
  message: string;
  data?: {
    calculationDate: string;
    alreadyCompleted: boolean;
    distributedCustomers: number;
    totalDistributedAmount: number;
  };
}

type AdjustmentMode = "entitlement" | "received" | "pool";
type SavedAdjustment =
  | {
      mode: "entitlement";
      amount: number;
      customer: CustomerItem;
      totalEntitlementAmount: number;
      totalAccumulatedAmount: number;
    }
  | {
      mode: "received";
      amount: number;
      customer: CustomerItem;
      totalEntitlementAmount: number;
      totalAccumulatedAmount: number;
      remainingAmount: number;
    }
  | {
      mode: "pool";
      amount: number;
      calculationDate: string;
      totalManualPoolAmount: number;
    };

interface Props {
  pageInfo?: any;
}

const formatMoney = (amount: number) => `${amount.toLocaleString("vi-VN")} đ`;

const moneyFormatter = (value?: string | number) =>
  value === undefined || value === null || value === ""
    ? ""
    : `${String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ".")} đ`;

const moneyParser = (value?: string) => {
  const input = (value || "").trim();
  const digits = input.replace(/[^0-9]/g, "");
  if (!digits) return input.startsWith("-") ? "-" : "";
  return `${input.startsWith("-") ? "-" : ""}${digits}`;
};

export default function AccumulationEntitlementCtrl({ pageInfo }: Props) {
  const [form] = Form.useForm<EntitlementFormValues>();
  const [mode, setMode] = useState<AdjustmentMode>("entitlement");
  const [selectedCustomer, setSelectedCustomer] = useState<CustomerItem | null>(
    null
  );
  const [pickerOpen, setPickerOpen] = useState(false);
  const [customerPickerReset, setCustomerPickerReset] = useState(0);
  const [selectionError, setSelectionError] = useState("");
  const [saving, setSaving] = useState(false);
  const [enteredAmount, setEnteredAmount] = useState<number | null>(null);
  const savingRef = useRef(false);
  const poolRequestIdRef = useRef<string | null>(null);
  const receivedRequestIdRef = useRef<string | null>(null);
  const [receivedBalance, setReceivedBalance] = useState<
    ReceivedBalanceResponse["data"] | null
  >(null);
  const [receivedLoading, setReceivedLoading] = useState(false);
  const [receivedError, setReceivedError] = useState("");
  const [receivedRefresh, setReceivedRefresh] = useState(0);
  const [error, setError] = useState("");
  const [saved, setSaved] = useState<SavedAdjustment | null>(null);
  const [runDate, setRunDate] = useState(businessDate);
  const [poolRefresh, setPoolRefresh] = useState(0);
  const [poolBalance, setPoolBalance] = useState<
    PoolBalanceResponse["data"] | null
  >(null);
  const [poolLoading, setPoolLoading] = useState(false);
  const [poolError, setPoolError] = useState("");
  const [historyDate, setHistoryDate] = useState(businessDate);
  const [historyPage, setHistoryPage] = useState(1);
  const [historySearchDraft, setHistorySearchDraft] = useState("");
  const [historySearch, setHistorySearch] = useState("");
  const [historyRefresh, setHistoryRefresh] = useState(0);
  const [historyRows, setHistoryRows] = useState<DistributionItem[]>([]);
  const [historyTotal, setHistoryTotal] = useState(0);
  const [historyFilteredTotal, setHistoryFilteredTotal] = useState(0);
  const [historyAmount, setHistoryAmount] = useState(0);
  const [runStatus, setRunStatus] = useState<string | null>(null);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyError, setHistoryError] = useState("");
  const [running, setRunning] = useState(false);
  const runningRef = useRef(false);
  const [runNotice, setRunNotice] = useState<{
    type: "success" | "error";
    message: string;
  } | null>(null);

  useEffect(() => {
    let cancelled = false;
    const loadPool = async () => {
      setPoolLoading(true);
      setPoolBalance(null);
      setPoolError("");
      try {
        const response = await request<PoolBalanceResponse>({
          url: "/admin/commission-pools/topups",
          options: {
            method: "get",
            params: { calculationDate: runDate },
          },
        });
        if (cancelled) return;
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data
        ) {
          throw new Error(
            response?.data?.message || "Không thể tải số tiền quỹ chia."
          );
        }
        setPoolBalance(response.data.data);
      } catch (cause: any) {
        if (!cancelled) {
          setPoolError(cause?.message || "Không thể tải số tiền quỹ chia.");
        }
      } finally {
        if (!cancelled) setPoolLoading(false);
      }
    };
    loadPool();
    return () => {
      cancelled = true;
    };
  }, [runDate, poolRefresh]);

  useEffect(() => {
    if (mode !== "received" || !selectedCustomer) {
      setReceivedBalance(null);
      setReceivedError("");
      return;
    }
    let cancelled = false;
    const customerId = selectedCustomer.id;
    const loadReceived = async () => {
      setReceivedLoading(true);
      setReceivedError("");
      setReceivedBalance(null);
      try {
        const response = await request<ReceivedBalanceResponse>({
          url: "/admin/commission-wallets/received-adjustments/balance",
          options: { method: "get", params: { customerId } },
        });
        if (cancelled) return;
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data
        ) {
          throw new Error(
            response?.data?.message || "Không thể tải số đã nhận."
          );
        }
        setReceivedBalance(response.data.data);
      } catch (cause: any) {
        if (!cancelled)
          setReceivedError(cause?.message || "Không thể tải số đã nhận.");
      } finally {
        if (!cancelled) setReceivedLoading(false);
      }
    };
    loadReceived();
    return () => {
      cancelled = true;
    };
  }, [mode, selectedCustomer?.id, receivedRefresh]);

  useEffect(() => {
    let cancelled = false;
    const loadHistory = async () => {
      setHistoryLoading(true);
      setHistoryError("");
      try {
        const response = await request<DistributionsResponse>({
          url: "/admin/commission-pools/distributions",
          options: {
            method: "get",
            params: {
              calculationDate: historyDate,
              skip: (historyPage - 1) * HISTORY_PAGE_SIZE,
              limit: HISTORY_PAGE_SIZE,
              ...(historySearch ? { search: historySearch } : {}),
            },
          },
        });
        if (cancelled) return;
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data
        ) {
          throw new Error(
            response?.data?.message || "Không thể tải lịch sử chia tích sản."
          );
        }
        setHistoryRows(
          Array.isArray(response.data.data.items)
            ? response.data.data.items
            : []
        );
        setHistoryTotal(Number(response.data.data.total) || 0);
        setHistoryFilteredTotal(
          Number(
            response.data.data.filteredTotal ?? response.data.data.total
          ) || 0
        );
        setHistoryAmount(
          Number(response.data.data.totalDistributedAmount) || 0
        );
        setRunStatus(response.data.data.runStatus);
        if (response.data.data.runStatus === "failed") {
          setHistoryError(
            response.data.data.runError || "Kỳ quyết toán này đã lỗi."
          );
        }
      } catch (cause: any) {
        if (cancelled) return;
        setHistoryRows([]);
        setHistoryTotal(0);
        setHistoryFilteredTotal(0);
        setHistoryAmount(0);
        setRunStatus(null);
        setHistoryError(
          cause?.message || "Không thể tải lịch sử chia tích sản."
        );
      } finally {
        if (!cancelled) setHistoryLoading(false);
      }
    };
    loadHistory();
    return () => {
      cancelled = true;
    };
  }, [historyDate, historyPage, historyRefresh, historySearch]);

  const runCron = async () => {
    if (runningRef.current) return;
    runningRef.current = true;
    setRunning(true);
    setRunNotice(null);
    try {
      const response = await request<RunResponse>({
        url: "/admin/commission-pools/run",
        options: { method: "post", data: { calculationDate: runDate } },
      });
      if (
        response?.status !== 200 ||
        response.data?.code !== 0 ||
        !response.data.data
      ) {
        throw new Error(
          response?.data?.message || "Không thể chạy quyết toán tích sản."
        );
      }
      const result = response.data.data;
      setRunNotice({
        type: "success",
        message: result.alreadyCompleted
          ? `Ngày ${runDate} đã quyết toán trước đó; không chia lần hai.`
          : `Đã chia ${formatMoney(result.totalDistributedAmount)} cho ${
              result.distributedCustomers
            } khách hàng ngày ${runDate}.`,
      });
      setHistoryPage(1);
      setHistoryDate(runDate);
      setHistoryRefresh((value) => value + 1);
      setPoolRefresh((value) => value + 1);
    } catch (cause: any) {
      setRunNotice({
        type: "error",
        message: cause?.message || "Không thể chạy quyết toán tích sản.",
      });
    } finally {
      runningRef.current = false;
      setRunning(false);
    }
  };

  const confirmRun = () => {
    Modal.confirm({
      title: `Quyết toán tích sản ngày ${runDate}?`,
      content:
        "Hãy cộng đủ quỹ trước khi chạy. Sau khi kỳ bắt đầu quyết toán, không thể cộng hoặc trừ quỹ của ngày này; kỳ đã hoàn tất sẽ không chia lại.",
      okText: "Chạy quyết toán",
      cancelText: "Hủy",
      onOk: runCron,
    });
  };

  const openPicker = () => {
    setPickerOpen(true);
  };

  const chooseCustomer = (customer: CustomerItem) => {
    setSelectedCustomer(customer);
    receivedRequestIdRef.current = null;
    if (mode === "received") {
      form.resetFields();
      setEnteredAmount(null);
      setSaved(null);
    }
    setSelectionError("");
    setPickerOpen(false);
  };

  const submit = async (values: EntitlementFormValues) => {
    if (mode !== "pool" && !selectedCustomer) {
      setSelectionError("Vui lòng chọn khách hàng cần điều chỉnh.");
      return;
    }
    if (mode === "received" && !receivedBalance) {
      setReceivedError("Chưa tải được số đã nhận hiện tại. Vui lòng thử lại.");
      return;
    }
    if (savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    setError("");
    setSaved(null);
    try {
      if (mode === "pool") {
        // Giữ requestId nếu cần thử lại sau lỗi mạng để API không cộng/trừ hai lần.
        if (!poolRequestIdRef.current) {
          poolRequestIdRef.current =
            window.crypto?.randomUUID?.() ||
            `pool-${Date.now()}-${Math.random().toString(36).slice(2)}`;
        }
        const response = await request<PoolResponse>({
          url: "/admin/commission-pools/topups",
          options: {
            method: "post",
            data: {
              amount: values.amount,
              requestId: poolRequestIdRef.current,
            },
          },
        });
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data
        ) {
          throw new Error(
            response?.data?.message || "Không thể điều chỉnh quỹ chia tích sản."
          );
        }
        setSaved({
          mode: "pool",
          amount: values.amount,
          calculationDate: response.data.data.calculationDate,
          totalManualPoolAmount: response.data.data.totalManualPoolAmount,
        });
        setPoolRefresh((value) => value + 1);
        poolRequestIdRef.current = null;
      } else if (mode === "received") {
        const customer = selectedCustomer!;
        if (!receivedRequestIdRef.current) {
          receivedRequestIdRef.current = uuid();
        }
        const response = await request<ReceivedAdjustmentResponse>({
          url: "/admin/commission-wallets/received-adjustments",
          options: {
            method: "post",
            data: {
              customerId: customer.id,
              amount: values.amount,
              requestId: receivedRequestIdRef.current,
            },
          },
        });
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data
        ) {
          throw new Error(
            response?.data?.message || "Không thể điều chỉnh số đã nhận."
          );
        }
        setSaved({
          mode: "received",
          customer,
          amount: values.amount,
          totalEntitlementAmount: response.data.data.totalEntitlementAmount,
          totalAccumulatedAmount: response.data.data.totalAccumulatedAmount,
          remainingAmount: response.data.data.remainingAmount,
        });
        setReceivedBalance(response.data.data);
        setReceivedRefresh((value) => value + 1);
        receivedRequestIdRef.current = null;
      } else {
        const customer = selectedCustomer!;
        // Điều chỉnh hạn mức được tích, không thay đổi tiền đã nhận.
        const response = await request<EntitlementResponse>({
          url: "/admin/commission-wallets/entitlements",
          options: {
            method: "post",
            data: { customerId: customer.id, amount: values.amount },
          },
        });
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data
        ) {
          throw new Error(
            response?.data?.message || "Không thể điều chỉnh hạn mức tích sản."
          );
        }
        setSaved({
          mode: "entitlement",
          customer,
          amount: values.amount,
          totalEntitlementAmount: response.data.data.totalEntitlementAmount,
          totalAccumulatedAmount: response.data.data.totalAccumulatedAmount,
        });
        setSelectedCustomer(null);
        setCustomerPickerReset((value) => value + 1);
      }
      form.resetFields();
      setEnteredAmount(null);
    } catch (cause: any) {
      if (mode === "received") {
        setReceivedRefresh((value) => value + 1);
      }
      setError(
        `${
          cause?.message ||
          (mode === "pool"
            ? "Không thể điều chỉnh quỹ chia tích sản."
            : mode === "received"
            ? "Không thể điều chỉnh số đã nhận tích sản."
            : "Không thể điều chỉnh hạn mức tích sản.")
        } Nếu kết nối bị gián đoạn, hãy kiểm tra kết quả trước khi gửi lại để tránh điều chỉnh hai lần.`
      );
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };

  const historyColumns: any[] = [
    {
      title: "Khách hàng",
      dataIndex: "name",
      key: "customer",
      width: 245,
      render: (_: unknown, item: DistributionItem) => (
        <div>
          <Typography.Text strong>
            {item.name || item.username || `Khách hàng #${item.customerId}`}
          </Typography.Text>
          <div>
            <Typography.Text type="secondary">
              ID {item.customerId}
              {item.phone ? ` · ${item.phone}` : ""}
            </Typography.Text>
          </div>
          {item.email && (
            <div>
              <Typography.Text type="secondary" copyable={{ text: item.email }}>
                {item.email}
              </Typography.Text>
            </div>
          )}
        </div>
      ),
    },
    {
      title: "Được chia trong ngày",
      dataIndex: "distributedAmount",
      key: "distributedAmount",
      align: "right",
      width: 180,
      render: (value: number) => (
        <Typography.Text strong>{formatMoney(value)}</Typography.Text>
      ),
    },
    {
      title: "Tổng hạn mức hiện tại",
      dataIndex: "totalEntitlementAmount",
      key: "totalEntitlementAmount",
      align: "right",
      width: 185,
      render: (value: number) => formatMoney(value),
    },
    {
      title: "Còn được nhận hiện tại",
      dataIndex: "remainingAmount",
      key: "remainingAmount",
      align: "right",
      width: 190,
      render: (value: number) => formatMoney(value),
    },
  ];

  return (
    <div style={{ maxWidth: 1320, margin: "0 auto", padding: "24px 16px" }}>
      <Space direction="vertical" size="large" style={{ width: "100%" }}>
        <div>
          <Typography.Title level={3} style={{ marginBottom: 4 }}>
            Quản lý tiêu dùng tích sản
          </Typography.Title>
        </div>

        {error && (
          <Alert
            type="error"
            showIcon
            message="Chưa xác nhận được kết quả"
            description={error}
            closable
            onClose={() => setError("")}
            role="alert"
          />
        )}

        {saved?.mode === "entitlement" && (
          <Alert
            type="success"
            showIcon
            message={`Đã ${saved.amount > 0 ? "cộng" : "trừ"} ${formatMoney(
              Math.abs(saved.amount)
            )} cho ${
              saved.customer.name || `khách hàng #${saved.customer.id}`
            }`}
            description={`Tổng hạn mức hiện tại: ${formatMoney(
              saved.totalEntitlementAmount
            )}. Đã nhận tích sản: ${formatMoney(
              saved.totalAccumulatedAmount
            )}.`}
            role="status"
          />
        )}

        {saved?.mode === "pool" && (
          <Alert
            type="success"
            showIcon
            message={`Đã ${saved.amount > 0 ? "cộng" : "trừ"} ${formatMoney(
              Math.abs(saved.amount)
            )} ${saved.amount > 0 ? "vào" : "khỏi"} quỹ chia`}
            description={`Ngày quỹ: ${
              saved.calculationDate
            }. Tổng điều chỉnh thủ công của ngày: ${formatMoney(
              saved.totalManualPoolAmount
            )}. Quỹ sẽ được chốt để chia lúc 07:00 ngày hôm sau.`}
            role="status"
          />
        )}

        {saved?.mode === "received" && (
          <Alert
            type="success"
            showIcon
            message={`Đã ${saved.amount > 0 ? "cộng" : "trừ"} ${formatMoney(
              Math.abs(saved.amount)
            )} số tích sản đã nhận của ${
              saved.customer.name || `khách hàng #${saved.customer.id}`
            }`}
            description={`Đã nhận hiện tại: ${formatMoney(
              saved.totalAccumulatedAmount
            )}. Còn được nhận: ${formatMoney(
              saved.remainingAmount
            )}. Tổng hạn mức không đổi: ${formatMoney(
              saved.totalEntitlementAmount
            )}. Ví hoa hồng không thay đổi.`}
            role="status"
          />
        )}

        <Row gutter={[16, 16]} align="stretch">
          <Col xs={24} xl={14}>
            <Card
              title="Điều chỉnh hạn mức / đã nhận / quỹ chia"
              style={{ height: "100%" }}
            >
              <Form<EntitlementFormValues>
                form={form}
                layout="vertical"
                onFinish={submit}
                scrollToFirstError
                aria-busy={saving}
              >
                <Form.Item label="Mục điều chỉnh">
                  <Radio.Group
                    value={mode}
                    disabled={saving}
                    onChange={(event) => {
                      setMode(event.target.value as AdjustmentMode);
                      setSelectedCustomer(null);
                      setPickerOpen(false);
                      setSelectionError("");
                      setError("");
                      setSaved(null);
                      setEnteredAmount(null);
                      poolRequestIdRef.current = null;
                      receivedRequestIdRef.current = null;
                      form.resetFields();
                    }}
                  >
                    <Radio.Button value="entitlement">
                      Hạn mức khách hàng
                    </Radio.Button>
                    <Radio.Button value="received">
                      Đã nhận tích sản
                    </Radio.Button>
                    <Radio.Button value="pool">Quỹ chia hằng ngày</Radio.Button>
                  </Radio.Group>
                </Form.Item>

                {/* {mode === "pool" && (
                  <Alert
                    type="info"
                    showIcon
                    message="Điều chỉnh quỹ chia của hôm nay"
                    description="Số tiền cộng/trừ được ghi cho ngày hiện tại theo giờ Việt Nam và đưa vào quỹ chia lúc 07:00 ngày mai. Chỉ được trừ phần admin đã cộng trong cùng ngày; thao tác này không tăng hạn mức cho một khách hàng."
                    style={{ marginBottom: 24 }}
                  />
                )} */}

                {mode !== "pool" && (
                  <Form.Item
                    label="Khách hàng"
                    required
                    validateStatus={selectionError ? "error" : undefined}
                    help={selectionError || undefined}
                  >
                    <Button
                      onClick={openPicker}
                      aria-label="Chọn khách hàng"
                      disabled={saving}
                    >
                      {selectedCustomer ? "Đổi khách hàng" : "Chọn khách hàng"}
                    </Button>
                    {selectedCustomer && (
                      <div style={{ marginTop: 12 }}>
                        <Typography.Text strong>
                          {selectedCustomer.name ||
                            `Khách hàng #${selectedCustomer.id}`}
                        </Typography.Text>
                        <br />
                        <Typography.Text type="secondary">
                          ID {selectedCustomer.id}
                          {selectedCustomer.phone
                            ? ` · ${selectedCustomer.phone}`
                            : ""}
                          {selectedCustomer.email
                            ? ` · ${selectedCustomer.email}`
                            : ""}
                        </Typography.Text>
                      </div>
                    )}
                  </Form.Item>
                )}

                {mode === "received" && selectedCustomer && (
                  <div style={{ marginBottom: 24 }}>
                    {receivedError && (
                      <Alert
                        type="error"
                        showIcon
                        message={receivedError}
                        role="alert"
                      />
                    )}
                    {receivedLoading && (
                      <Typography.Text type="secondary">
                        Đang tải số đã nhận...
                      </Typography.Text>
                    )}
                    {receivedBalance && (
                      <Row gutter={[16, 8]}>
                        <Col xs={24} sm={8}>
                          <Statistic
                            title="Tổng hạn mức"
                            value={receivedBalance.totalEntitlementAmount}
                            suffix="đ"
                          />
                        </Col>
                        <Col xs={24} sm={8}>
                          <Statistic
                            title="Đã nhận"
                            value={receivedBalance.totalAccumulatedAmount}
                            suffix="đ"
                          />
                        </Col>
                        <Col xs={24} sm={8}>
                          <Statistic
                            title="Còn được nhận"
                            value={receivedBalance.remainingAmount}
                            suffix="đ"
                          />
                        </Col>
                      </Row>
                    )}
                  </div>
                )}

                <Form.Item
                  name="amount"
                  label={
                    mode === "pool"
                      ? "Số tiền điều chỉnh quỹ chia"
                      : mode === "received"
                      ? "Số tiền điều chỉnh đã nhận"
                      : "Số tiền điều chỉnh hạn mức"
                  }
                  extra={
                    mode === "pool"
                      ? "Số dương: cộng quỹ. Số âm: trừ phần admin đã cộng hôm nay."
                      : mode === "received"
                      ? "Số dương: tăng đã nhận, giảm phần còn được nhận. Số âm: giảm đã nhận, tăng phần còn được nhận. Không đổi ví hoa hồng."
                      : "Số dương: cộng hạn mức. Số âm: trừ hạn mức"
                  }
                  rules={[
                    {
                      required: true,
                      message: "Vui lòng nhập số tiền điều chỉnh",
                    },
                    {
                      type: "number",
                      min: -Number.MAX_SAFE_INTEGER,
                      max: Number.MAX_SAFE_INTEGER,
                      message: "Số tiền vượt giới hạn cho phép",
                    },
                    {
                      validator: (_, value) =>
                        value === undefined ||
                        (Number.isSafeInteger(value) && value !== 0)
                          ? Promise.resolve()
                          : Promise.reject(new Error("Nhập số nguyên khác 0")),
                    },
                    {
                      validator: (_, value) =>
                        mode !== "received" ||
                        value === undefined ||
                        !receivedBalance ||
                        (receivedBalance.totalAccumulatedAmount + value >= 0 &&
                          receivedBalance.totalAccumulatedAmount + value <=
                            receivedBalance.totalEntitlementAmount)
                          ? Promise.resolve()
                          : Promise.reject(
                              new Error(
                                "Số đã nhận sau điều chỉnh phải nằm từ 0 đến tổng hạn mức"
                              )
                            ),
                    },
                  ]}
                >
                  <InputNumber
                    disabled={saving}
                    min={-Number.MAX_SAFE_INTEGER}
                    max={Number.MAX_SAFE_INTEGER}
                    precision={0}
                    formatter={moneyFormatter}
                    parser={moneyParser as any}
                    placeholder="Ví dụ: 1.000.000 hoặc -1.000.000"
                    onChange={(value) => {
                      poolRequestIdRef.current = null;
                      receivedRequestIdRef.current = null;
                      setEnteredAmount(
                        typeof value === "number" ? value : null
                      );
                    }}
                    style={{ width: "100%" }}
                  />
                </Form.Item>

                {mode === "received" &&
                  receivedBalance &&
                  enteredAmount !== null &&
                  enteredAmount !== 0 &&
                  receivedBalance.totalAccumulatedAmount + enteredAmount >= 0 &&
                  receivedBalance.totalAccumulatedAmount + enteredAmount <=
                    receivedBalance.totalEntitlementAmount && (
                    <Alert
                      type="info"
                      showIcon
                      style={{ marginBottom: 20 }}
                      message={`Sau điều chỉnh: đã nhận ${formatMoney(
                        receivedBalance.totalAccumulatedAmount + enteredAmount
                      )}, còn được nhận ${formatMoney(
                        receivedBalance.remainingAmount - enteredAmount
                      )}`}
                    />
                  )}

                <Button
                  type="primary"
                  htmlType="submit"
                  icon={
                    enteredAmount !== null && enteredAmount < 0 ? (
                      <MinusOutlined />
                    ) : (
                      <PlusOutlined />
                    )
                  }
                  danger={enteredAmount !== null && enteredAmount < 0}
                  loading={saving}
                  disabled={
                    saving ||
                    (mode === "received" &&
                      (!receivedBalance || receivedLoading))
                  }
                >
                  {saving
                    ? "Đang xử lý..."
                    : enteredAmount !== null && enteredAmount < 0
                    ? mode === "pool"
                      ? "Trừ quỹ chia"
                      : mode === "received"
                      ? "Trừ đã nhận"
                      : "Trừ hạn mức"
                    : mode === "pool"
                    ? "Cộng quỹ chia"
                    : mode === "received"
                    ? "Cộng đã nhận"
                    : "Cộng hạn mức"}
                </Button>
              </Form>
            </Card>
          </Col>
          <Col xs={24} xl={10}>
            <Card
              title="Chạy chia tích sản thủ công"
              style={{ height: "100%" }}
            >
              <Space
                direction="vertical"
                size="middle"
                style={{ width: "100%" }}
              >
                {/* <Typography.Text type="secondary">
                  Chọn ngày cần quyết toán. Hãy cộng đủ quỹ của ngày đó trước
                  khi chạy; kỳ hoàn tất sẽ không chia lại.
                </Typography.Text> */}
                <div>
                  <Typography.Text strong>Ngày quyết toán</Typography.Text>
                  <div style={{ marginTop: 8 }}>
                    <DatePicker
                      value={moment(runDate, "YYYY-MM-DD")}
                      format="DD/MM/YYYY"
                      allowClear={false}
                      disabled={running}
                      disabledDate={(date) =>
                        Boolean(
                          date && date.format("YYYY-MM-DD") > businessDate()
                        )
                      }
                      onChange={(date) => {
                        if (date) {
                          setRunDate(date.format("YYYY-MM-DD"));
                          setRunNotice(null);
                        }
                      }}
                      style={{ width: "100%" }}
                    />
                  </div>
                </div>
                <div
                  role="status"
                  aria-live="polite"
                  aria-atomic="true"
                  style={{
                    padding: "16px 20px",
                    border: "1px solid #d9e8d2",
                    borderRadius: 8,
                    background: "#f7fbf5",
                  }}
                >
                  <Statistic
                    title={
                      poolBalance?.runStatus === "completed"
                        ? "Quỹ chia đã chốt"
                        : "Quỹ chia tích sản"
                    }
                    value={
                      poolLoading || !poolBalance
                        ? "—"
                        : poolBalance.settledPoolAmount ??
                          poolBalance.manualPoolAmount
                    }
                    suffix={poolLoading || !poolBalance ? undefined : "đ"}
                    groupSeparator="."
                  />
                  <Typography.Text type="secondary">
                    {poolLoading
                      ? "Đang tải quỹ của ngày đã chọn..."
                      : poolBalance?.runStatus === "completed"
                      ? `Tổng quỹ đã quyết toán ngày ${runDate}.`
                      : ""}
                  </Typography.Text>
                </div>
                {poolError && (
                  <Alert
                    type="error"
                    showIcon
                    message={poolError}
                    action={
                      <Button
                        size="small"
                        onClick={() => setPoolRefresh((value) => value + 1)}
                      >
                        Thử lại
                      </Button>
                    }
                  />
                )}
                <Button
                  type="primary"
                  icon={<PlayCircleOutlined />}
                  aria-label="Chạy chia tích sản"
                  loading={running}
                  disabled={running}
                  onClick={confirmRun}
                >
                  {running ? "Đang quyết toán..." : "Chạy chia tích sản"}
                </Button>
                {runNotice && (
                  <Alert
                    type={runNotice.type}
                    showIcon
                    message={runNotice.message}
                    role="status"
                  />
                )}
              </Space>
            </Card>
          </Col>
        </Row>

        <Card title="Chi tiết chia tích sản">
          <Space align="center" wrap style={{ marginBottom: 20 }}>
            <Typography.Text strong>Ngày xem dữ liệu</Typography.Text>
            <DatePicker
              aria-label="Ngày xem lịch sử chia tích sản"
              value={moment(historyDate, "YYYY-MM-DD")}
              format="DD/MM/YYYY"
              allowClear={false}
              onChange={(date) => {
                if (date) {
                  setHistoryPage(1);
                  setHistoryDate(date.format("YYYY-MM-DD"));
                }
              }}
            />
            <Button
              icon={<ReloadOutlined />}
              aria-label="Tải lại lịch sử chia tích sản"
              onClick={() => setHistoryRefresh((value) => value + 1)}
            />
            <Input.Search
              aria-label="Tìm khách hàng được chia theo số điện thoại, tên hoặc email"
              placeholder="Tìm SĐT, tên hoặc email"
              value={historySearchDraft}
              allowClear
              style={{ width: 300, maxWidth: "100%", marginBottom: 0 }}
              onChange={(event) => {
                setHistorySearchDraft(event.target.value);
                if (!event.target.value && historySearch) {
                  setHistoryPage(1);
                  setHistorySearch("");
                }
              }}
              onSearch={(value) => {
                setHistoryPage(1);
                setHistorySearch(value.trim());
              }}
            />
          </Space>
          <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
            <Col xs={12} md={8}>
              <Statistic title="Số người được chia" value={historyTotal} />
            </Col>
            <Col xs={12} md={8}>
              <Statistic
                title="Tổng đã chia"
                value={historyAmount}
                suffix="đ"
                groupSeparator="."
              />
            </Col>
            <Col xs={24} md={8}>
              <Typography.Text type="secondary">
                Trạng thái ngày {historyDate}
              </Typography.Text>
              <div>
                <Typography.Text strong>
                  {runStatus === "completed"
                    ? "Đã hoàn tất"
                    : runStatus === "failed"
                    ? "Chạy lỗi"
                    : runStatus && runStatus !== "pending"
                    ? "Đang xử lý"
                    : "Chưa chạy"}
                </Typography.Text>
              </div>
            </Col>
          </Row>
          {historyError && (
            <Alert
              type="error"
              showIcon
              message={historyError}
              style={{ marginBottom: 16 }}
              role="alert"
            />
          )}
          <ProTable<DistributionItem, Record<string, never>>
            type="table"
            rowKey="customerId"
            search={false}
            options={false}
            toolBarRender={false}
            columns={historyColumns}
            dataSource={historyRows}
            loading={historyLoading}
            scroll={{ x: 850 }}
            locale={{
              emptyText: historySearch
                ? "Không tìm thấy khách hàng phù hợp trong ngày này"
                : runStatus === "completed"
                ? "Không có khách hàng được chia trong ngày này"
                : "Chưa có dữ liệu chia tích sản",
            }}
            pagination={{
              current: historyPage,
              pageSize: HISTORY_PAGE_SIZE,
              total: historyFilteredTotal,
              showSizeChanger: false,
              showTotal: (total: number, range: [number, number]) =>
                `${range[0]}–${range[1]} trên ${total} khách hàng`,
            }}
            onChange={(pagination) => setHistoryPage(pagination.current || 1)}
          />
          <Typography.Text type="secondary">
            Số được chia là của ngày đã chọn; hạn mức và phần còn được nhận là
            số dư hiện tại.
          </Typography.Text>
        </Card>
      </Space>

      <CustomerPicker
        pageInfo={pageInfo}
        visible={pickerOpen}
        selectedCustomer={selectedCustomer}
        resetKey={customerPickerReset}
        onSelect={chooseCustomer}
        onCancel={() => setPickerOpen(false)}
      />
    </div>
  );
}
