import React, { useCallback, useEffect, useState } from "react";
import {
  Alert,
  Button,
  Card,
  Col,
  Divider,
  Form,
  Input,
  InputNumber,
  Row,
  Space,
  Spin,
} from "antd";
import { DeleteOutlined, PlusOutlined, SaveOutlined } from "@ant-design/icons";
import moment, { Moment } from "moment";
import { helper } from "@src/controls/controlHelper";

type ApiMethod = "GET" | "POST";

interface ConfigBussinessCtrlProps {
  pageInfo: any;
}

interface AgencyTierFormValue {
  level: number;
  name: string;
  personalRevenueRequired: number;
  smallBranchRevenueRequired: number;
  systemRevenueRateBps: number;
  sameTierRateBps: number;
}

interface PolicyFormValue {
  name?: string;
  status: "draft" | "active" | "expired";
  effectiveFrom?: Moment | null;
  effectiveTo?: Moment | null;
  directCommissionRateBps: number;
  directConsumptionPointRateBps: number;
  accumulationRevenueRateBps: number;
  accumulationIncomeRateBps: number;
  accumulationBelow50MRateBps: number;
  accumulationFrom50MRateBps: number;
  smallBranchRateBps: number;
  smallBranchWeeklyLimit: number;
  positiveIncomeRateBps: number;
  positiveRepurchaseAmount: number;
  positiveUplineRewardRateBps: number;
  resonanceRateBps: number;
  resonanceMinimumOrderAmount: number;
  agencyTiers: AgencyTierFormValue[];
}

const RATE_FIELDS = [
  "directCommissionRateBps",
  "directConsumptionPointRateBps",
  "accumulationRevenueRateBps",
  "accumulationIncomeRateBps",
  "accumulationBelow50MRateBps",
  "accumulationFrom50MRateBps",
  "smallBranchRateBps",
  "positiveIncomeRateBps",
  "positiveUplineRewardRateBps",
  "resonanceRateBps",
] as const;

const moneyFormatter = (value?: string | number) =>
  value === undefined || value === null
    ? ""
    : `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ".");

const moneyParser = (value?: string) =>
  Number((value || "").replace(/\./g, "").replace(/[^0-9]/g, ""));

const MoneyField = ({
  name,
  label,
  help,
}: {
  name: string | Array<string | number>;
  label: string;
  help?: string;
}) => (
  <Form.Item
    name={name}
    label={label}
    extra={help}
    rules={[
      { required: true, message: `Vui lòng nhập ${label.toLowerCase()}` },
      {
        type: "number",
        min: 0,
        message: "Số tiền không được âm",
      },
    ]}
  >
    <InputNumber
      min={0}
      precision={0}
      formatter={(value) => `${moneyFormatter(value)} đ`}
      parser={moneyParser as any}
      style={{ width: "100%" }}
    />
  </Form.Item>
);

const PercentField = ({
  name,
  label,
  max = 100,
  help,
}: {
  name: string | Array<string | number>;
  label: string;
  max?: number;
  help?: string;
}) => (
  <Form.Item
    name={name}
    label={label}
    extra={help}
    rules={[
      { required: true, message: `Vui lòng nhập ${label.toLowerCase()}` },
      {
        type: "number",
        min: 0,
        max,
        message: `Tỷ lệ phải từ 0 đến ${max}%`,
      },
    ]}
  >
    <InputNumber
      min={0}
      max={max}
      precision={2}
      step={0.1}
      formatter={(value) =>
        value === undefined || value === null ? "" : `${value}%`
      }
      parser={
        ((value?: string) =>
          Number(
            (value || "").replace(",", ".").replace(/[^0-9.]/g, ""),
          )) as any
      }
      style={{ width: "100%" }}
    />
  </Form.Item>
);

const validateAgencyTiers = async (
  _: unknown,
  tiers?: AgencyTierFormValue[],
) => {
  if (!tiers || tiers.length === 0) {
    throw new Error("Cần ít nhất một cấp đại lý");
  }

  // Mục 6 - Thưởng đại lý: kiểm tra quan hệ giữa các cấp.
  // Quy tắc bắt buộc và giới hạn từng ô được kiểm tra ngay tại Form.Item.
  const completeTiers = tiers.filter(
    (tier) =>
      tier &&
      Number.isFinite(Number(tier.level)) &&
      String(tier.name || "").trim() &&
      Number.isFinite(Number(tier.personalRevenueRequired)) &&
      Number.isFinite(Number(tier.smallBranchRevenueRequired)) &&
      Number.isFinite(Number(tier.systemRevenueRateBps)),
  );
  if (completeTiers.length !== tiers.length) return;

  const levels = completeTiers.map((tier) => Number(tier.level));
  if (new Set(levels).size !== levels.length) {
    throw new Error("Level của các cấp đại lý không được trùng nhau");
  }

  const normalizedNames = completeTiers.map((tier) =>
    tier.name.trim().toLocaleLowerCase("vi"),
  );
  if (new Set(normalizedNames).size !== normalizedNames.length) {
    throw new Error("Tên các nhóm đại lý không được trùng nhau");
  }

  const sortedTiers = [...completeTiers].sort(
    (left, right) => Number(left.level) - Number(right.level),
  );
  for (let index = 1; index < sortedTiers.length; index += 1) {
    const previous = sortedTiers[index - 1];
    const current = sortedTiers[index];
    if (
      Number(current.personalRevenueRequired) <
      Number(previous.personalRevenueRequired)
    ) {
      throw new Error("Doanh số cá nhân phải tăng dần theo level");
    }
    if (
      Number(current.smallBranchRevenueRequired) <
      Number(previous.smallBranchRevenueRequired)
    ) {
      throw new Error("Doanh số nhóm nhỏ phải tăng dần theo level");
    }
    if (
      Number(current.systemRevenueRateBps) <=
      Number(previous.systemRevenueRateBps)
    ) {
      throw new Error(
        "Tỷ lệ thưởng doanh số hệ thống phải tăng dần theo level",
      );
    }
  }
};

const ConfigBussinessCtrl: React.FC<ConfigBussinessCtrlProps> = ({
  pageInfo,
}) => {
  const [form] = Form.useForm<PolicyFormValue>();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [latestPolicyId, setLatestPolicyId] = useState<number>();
  const [latestVersion, setLatestVersion] = useState(0);
  const [loadError, setLoadError] = useState("");

  const findApi = useCallback(
    (resource: string, method: ApiMethod) => {
      const resourceName = resource.toLowerCase();
      const api = (pageInfo?.apis || []).find((item: any) => {
        const url = String(item.url || "")
          .toLowerCase()
          .split("?")[0];
        return (
          String(item.method || "").toUpperCase() === method &&
          (url.endsWith(`/${resourceName}`) ||
            url.includes(`/${resourceName}/`))
        );
      });
      if (!api) {
        throw new Error(`Trang chưa cấu hình API ${method} cho ${resource}.`);
      }
      return api;
    },
    [pageInfo],
  );

  const callApi = useCallback(
    async (resource: string, method: ApiMethod, data: any) => {
      const api = findApi(resource, method);
      const response: any = await helper.callPageApi(pageInfo, api.name, data);
      if (!response || response.status !== 200 || response?.data?.code === 1) {
        throw new Error(
          response?.data?.message || `Không thể xử lý ${resource}.`,
        );
      }
      return response.data;
    },
    [findApi, pageInfo],
  );

  const loadPolicy = useCallback(async () => {
    setLoading(true);
    setLoadError("");
    try {
      const policyResponse = await callApi("commissionPolicy", "GET", {
        queryInput: JSON.stringify({}),
        limit: 1,
        skip: 0,
        sort: JSON.stringify([{ version: "desc" }, { id: "desc" }]),
      });
      const policy = policyResponse?.data?.[0];
      if (!policy) {
        setLatestPolicyId(undefined);
        setLatestVersion(0);
        form.resetFields();
        return;
      }

      const tierResponse = await callApi("commissionAgencyTier", "GET", {
        queryInput: JSON.stringify({ policyId: policy.id }),
        limit: 100,
        skip: 0,
        sort: JSON.stringify([{ level: "asc" }]),
      });
      const tiers = tierResponse?.data || [];
      setLatestPolicyId(Number(policy.id));
      setLatestVersion(Number(policy.version));

      const values: PolicyFormValue = {
        name: policy.name,
        status: policy.status,
        effectiveFrom:
          Number(policy.effectiveFrom) > 0
            ? moment(Number(policy.effectiveFrom))
            : null,
        effectiveTo: policy.effectiveTo
          ? moment(Number(policy.effectiveTo))
          : null,
        directCommissionRateBps: 0,
        directConsumptionPointRateBps: 0,
        accumulationRevenueRateBps: 0,
        accumulationIncomeRateBps: 0,
        accumulationBelow50MRateBps: 20,
        accumulationFrom50MRateBps: 80,
        smallBranchRateBps: 0,
        smallBranchWeeklyLimit: Number(policy.smallBranchWeeklyLimit),
        positiveIncomeRateBps: 0,
        positiveRepurchaseAmount: Number(policy.positiveRepurchaseAmount),
        positiveUplineRewardRateBps: 0,
        resonanceRateBps: 0,
        resonanceMinimumOrderAmount: Number(policy.resonanceMinimumOrderAmount),
        agencyTiers: tiers.map((tier: any) => ({
          level: tier.level,
          name: tier.name,
          personalRevenueRequired: Number(tier.personalRevenueRequired),
          smallBranchRevenueRequired: Number(tier.smallBranchRevenueRequired),
          systemRevenueRateBps: Number(tier.systemRevenueRateBps || 0) / 100,
          sameTierRateBps: Number(tier.sameTierRateBps || 0) / 100,
        })),
      };
      RATE_FIELDS.forEach((field) => {
        values[field] = Number(policy[field] || 0) / 100;
      });
      form.setFieldsValue(values);
    } catch (error: any) {
      setLoadError(error?.message || "Không thể tải cấu hình kinh doanh.");
    } finally {
      setLoading(false);
    }
  }, [callApi, form]);

  useEffect(() => {
    loadPolicy();
  }, [loadPolicy]);

  const savePolicy = async (values: PolicyFormValue) => {
    setSaving(true);
    try {
      if (
        Math.round(
          (Number(values.accumulationBelow50MRateBps) +
            Number(values.accumulationFrom50MRateBps)) *
            100,
        ) !== 10000
      ) {
        throw new Error("Tổng tỷ lệ chia hai nhóm đơn phải bằng 100%.");
      }
      const { agencyTiers, effectiveFrom, effectiveTo, ...policyFields } =
        values;
      const policyPayload: any = {
        ...policyFields,
        version: latestVersion + 1,
        name: values.name?.trim(),
        status: "active",
        effectiveFrom: effectiveFrom?.valueOf() || 0,
        effectiveTo: effectiveTo?.valueOf() || null,
      };
      RATE_FIELDS.forEach((field) => {
        policyPayload[field] = Math.round(Number(values[field]) * 100);
      });

      policyPayload.agencyTiers = {
        create: (agencyTiers || []).map((tier) => ({
          level: Number(tier.level),
          name: tier.name.trim(),
          personalRevenueRequired: Number(tier.personalRevenueRequired),
          smallBranchRevenueRequired: Number(tier.smallBranchRevenueRequired),
          systemRevenueRateBps: Math.round(
            Number(tier.systemRevenueRateBps) * 100,
          ),
          sameTierRateBps: Math.round(Number(tier.sameTierRateBps) * 100),
        })),
      };

      // Mỗi lần lưu tạo một policy bất biến mới. Không sửa policy đã dùng để
      // việc chạy lại và đối soát hoa hồng luôn giữ đúng cấu hình theo version.
      // Các cấp đại lý được nested-create để policy và Mục 6 cùng thành công
      // hoặc cùng rollback trong một transaction của Prisma.
      const savedPolicy = await callApi(
        "commissionPolicy",
        "POST",
        policyPayload,
      );
      const savedPolicyId = Number(savedPolicy?.id);
      if (!savedPolicyId) {
        throw new Error("Không xác định được policy vừa lưu.");
      }

      helper.alert("Đã lưu cấu hình kinh doanh", "success");
      await loadPolicy();
    } catch (error: any) {
      helper.alert(
        error?.message || "Không thể lưu cấu hình kinh doanh",
        "error",
      );
    } finally {
      setSaving(false);
    }
  };

  return (
    <div style={{ padding: 24, maxWidth: 1440, margin: "0 auto" }}>
      {loadError && (
        <Alert
          type="error"
          showIcon
          message="Không thể tải cấu hình"
          description={loadError}
          style={{ marginBottom: 16 }}
        />
      )}

      {!loading && !loadError && !latestPolicyId && (
        <Alert
          type="warning"
          showIcon
          message="Hệ thống chưa có cấu hình kinh doanh"
          description="Các trường được để trống để người quản trị chủ động nhập cấu hình lần đầu. Lần lưu đầu tiên sẽ tạo version 1."
          style={{ marginBottom: 16 }}
        />
      )}

      <Spin spinning={loading} tip="Đang tải cấu hình...">
        <Form
          form={form}
          layout="vertical"
          onFinish={savePolicy}
          scrollToFirstError
          initialValues={{
            accumulationBelow50MRateBps: 20,
            accumulationFrom50MRateBps: 80,
          }}
        >
          <Card
            size="small"
            title="Thông tin chính sách"
            style={{ marginBottom: 16 }}
          >
            <Form.Item
              name="name"
              label="Tên chính sách"
              style={{ marginBottom: 0 }}
              rules={[
                { required: true, message: "Vui lòng nhập tên chính sách" },
              ]}
            >
              <Input
                maxLength={255}
                placeholder="Nhập tên chính sách"
                style={{ width: "100%" }}
              />
            </Form.Item>
          </Card>

          <Row gutter={16}>
            <Col xs={24} xl={12}>
              <Card
                size="small"
                title="1. Hoa hồng trực tiếp"
                style={{ marginBottom: 16 }}
              >
                <Row gutter={16}>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="directCommissionRateBps"
                      label="Hoa hồng tiền mặt"
                    />
                  </Col>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="directConsumptionPointRateBps"
                      label="Điểm tiêu dùng"
                    />
                  </Col>
                </Row>
              </Card>
            </Col>
            <Col xs={24} xl={12}>
              <Card
                size="small"
                title="2. Tiêu dùng tích sản"
                style={{ marginBottom: 16 }}
              >
                <Row gutter={16}>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="accumulationRevenueRateBps"
                      label="Trích từ doanh số hệ thống"
                    />
                  </Col>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="accumulationIncomeRateBps"
                      label="Trích từ thu nhập thành viên"
                    />
                  </Col>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="accumulationBelow50MRateBps"
                      label="Chia nhóm đơn dưới 50 triệu"
                    />
                  </Col>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="accumulationFrom50MRateBps"
                      label="Chia nhóm đơn từ 50 triệu"
                    />
                  </Col>
                </Row>
              </Card>
            </Col>
            <Col xs={24} xl={12}>
              <Card
                size="small"
                title="3. Thưởng doanh số nhóm nhỏ"
                style={{ marginBottom: 16 }}
              >
                <Row gutter={16}>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="smallBranchRateBps"
                      label="Tỷ lệ thưởng"
                    />
                  </Col>
                  <Col xs={24} md={12}>
                    <MoneyField
                      name="smallBranchWeeklyLimit"
                      label="Giới hạn mỗi tuần"
                    />
                  </Col>
                </Row>
              </Card>
            </Col>
            <Col xs={24} xl={12}>
              <Card
                size="small"
                title="4. Thưởng tích cực"
                style={{ marginBottom: 16 }}
              >
                <Row gutter={16}>
                  <Col xs={24} md={8}>
                    <PercentField
                      name="positiveIncomeRateBps"
                      label="Trích thu nhập"
                    />
                  </Col>
                  <Col xs={24} md={8}>
                    <MoneyField
                      name="positiveRepurchaseAmount"
                      label="Ngưỡng tái mua"
                    />
                  </Col>
                  <Col xs={24} md={8}>
                    <PercentField
                      name="positiveUplineRewardRateBps"
                      label="Thưởng mỗi TVBT"
                    />
                  </Col>
                </Row>
              </Card>
            </Col>
            <Col xs={24}>
              <Card
                size="small"
                title="5. Thưởng cộng hưởng"
                style={{ marginBottom: 16 }}
              >
                <Row gutter={16}>
                  <Col xs={24} md={12}>
                    <PercentField
                      name="resonanceRateBps"
                      label="Tỷ lệ cộng hưởng"
                    />
                  </Col>
                  <Col xs={24} md={12}>
                    <MoneyField
                      name="resonanceMinimumOrderAmount"
                      label="Đơn cá nhân tối thiểu"
                    />
                  </Col>
                </Row>
              </Card>
            </Col>
          </Row>

          <Card
            size="small"
            title="6. Thưởng đại lý"
            style={{ marginBottom: 16 }}
          >
            <Form.List
              name="agencyTiers"
              rules={[{ validator: validateAgencyTiers }]}
            >
              {(fields, { add, remove }, { errors }) => (
                <>
                  {fields.map((field, index) => (
                    <Card
                      key={field.key}
                      type="inner"
                      size="small"
                      title={`Cấp ${index + 1}`}
                      extra={
                        <Button
                          danger
                          type="text"
                          icon={<DeleteOutlined />}
                          aria-label={`Xóa cấp ${index + 1}`}
                          onClick={() => remove(field.name)}
                        />
                      }
                      style={{ marginBottom: 12 }}
                    >
                      <Row gutter={16}>
                        <Col xs={24} md={4}>
                          <Form.Item
                            name={[field.name, "level"]}
                            label="Level"
                            rules={[{ required: true, type: "number", min: 1 }]}
                          >
                            <InputNumber
                              min={1}
                              precision={0}
                              style={{ width: "100%" }}
                            />
                          </Form.Item>
                        </Col>
                        <Col xs={24} md={8}>
                          <Form.Item
                            name={[field.name, "name"]}
                            label="Tên nhóm"
                            rules={[
                              { required: true, message: "Nhập tên nhóm" },
                            ]}
                          >
                            <Input maxLength={255} />
                          </Form.Item>
                        </Col>
                        <Col xs={24} md={6}>
                          <MoneyField
                            name={[field.name, "personalRevenueRequired"]}
                            label="Doanh số cá nhân"
                          />
                        </Col>
                        <Col xs={24} md={6}>
                          <MoneyField
                            name={[field.name, "smallBranchRevenueRequired"]}
                            label="Doanh số nhóm nhỏ"
                          />
                        </Col>
                        <Col xs={24} md={6}>
                          <PercentField
                            name={[field.name, "systemRevenueRateBps"]}
                            label="Thưởng doanh số hệ thống"
                            max={5}
                          />
                        </Col>
                        <Col xs={24} md={6}>
                          <PercentField
                            name={[field.name, "sameTierRateBps"]}
                            label="Thưởng đồng cấp"
                            max={5}
                          />
                        </Col>
                      </Row>
                    </Card>
                  ))}
                  <Form.ErrorList errors={errors} />
                  <Button
                    type="dashed"
                    block
                    icon={<PlusOutlined />}
                    onClick={() =>
                      add({
                        level: fields.length + 1,
                      })
                    }
                  >
                    Thêm cấp đại lý
                  </Button>
                </>
              )}
            </Form.List>
          </Card>

          <Divider />
          <Space style={{ width: "100%", justifyContent: "flex-end" }}>
            <Button onClick={loadPolicy} disabled={saving}>
              Hủy thay đổi
            </Button>
            <Button
              type="primary"
              htmlType="submit"
              icon={<SaveOutlined />}
              loading={saving}
            >
              Lưu cấu hình
            </Button>
          </Space>
        </Form>
      </Spin>
    </div>
  );
};

export default ConfigBussinessCtrl;
