export default function OrderListCtrl() {
  const [activeTab, setActiveTab] = useState<string>("all");
  const {
    filters,
    updateFilter,
    resetFilters,
    buildQueryParams,
    updatePagination,
  } = useOrderFilters();
  const [searchType, setSearchType] = useState("id");
  const [searchValue, setSearchValue] = useState("");
  const [statusCounts, setStatusCounts] = useState({
    wait_for_confirmation: 0,
    wait_for_pickup: 0,
    shipping: 0,
    completed: 0,
    canceled: 0,
    refund: 0,
    refunded: 0,
  });
  const [dateRange, setDateRange] = useState<any>(null);

  const searchPlaceholders: Record<string, string> = {
    id: "Nhập mã đơn hàng",
    buyerName: "Nhập tên người mua",
    product: "Nhập tên sản phẩm",
    shipCode: "Nhập mã vận đơn",
    date: "Chọn khoảng thời gian",
  };

  const handleTabChange = (key: string) => {
    setActiveTab(key);
    updateFilter("status", key === "all" ? "" : key);
    updateFilter("subStatus", "all");
  };

  const handleSubStatusChange = (e: RadioChangeEvent) => {
    updateFilter("subStatus", e.target.value);
  };

  const handleSearchTypeChange = (value: string) => {
    setSearchType(value);
    setSearchValue("");
    if (value !== "date") {
      updateFilter("dateRange", undefined);
    }
  };

  const handleSearchValueChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchValue(e.target.value);
  };

  const handleApplySearch = () => {
    const queryInput: Record<string, any> = {};

    if (searchValue && searchType !== "date") {
      switch (searchType) {
        case "id":
          queryInput.id = searchValue;
          break;
        case "buyerName":
          queryInput.receiveName = { contains: searchValue };
          break;
        case "product":
          queryInput["orderItemInfos.name"] = { contains: searchValue };
          break;
        case "shipCode":
          queryInput.shipOrderCodeId = searchValue;
          break;
      }
      updateFilter("queryInput", queryInput);
    }
  };

  const getTotalOrders = () => {
    return Object.values(statusCounts).reduce((acc, curr) => acc + curr, 0);
  };

  const handleDateRangeChange = (dates: any) => {
    setDateRange(dates);
    if (dates) {
      updateFilter("dateRange", [
        dates[0].startOf("day").valueOf(),
        dates[1].endOf("day").valueOf(),
      ]);
    } else {
      updateFilter("dateRange", undefined);
    }
  };

  return (
    <StyledCard>
      {/* <TabsContainer>
        <StyledTabs activeKey={activeTab} onChange={handleTabChange}>
          <TabPane tab={`Tất cả`} key="all" />
          <TabPane
            tab={`Chờ xác nhận (${statusCounts.wait_for_confirmation})`}
            key="wait_for_confirmation"
          />
          <TabPane
            tab={`Chờ lấy hàng (${statusCounts.wait_for_pickup})`}
            key="wait_for_pickup"
          />
          <TabPane tab={`Đang giao (${statusCounts.shipping})`} key="shipping" />
          <TabPane
            tab={`Hoàn thành (${statusCounts.completed})`}
            key="completed"
          />
          <TabPane
            tab={`Trả hàng/Hoàn tiền/Hủy (${
              statusCounts.canceled +
              statusCounts.refund +
              statusCounts.refunded
            })`}
            key="canceled"
          />
        </StyledTabs>

        {activeTab === "wait_for_confirmation" && (
          <SubTabs value={filters.subStatus} onChange={handleSubStatusChange}>
            <Radio.Button value="all">Tất cả</Radio.Button>
            <Radio.Button value="pending">
              Chưa xử lý ({statusCounts.wait_for_confirmation})
            </Radio.Button>
            <Radio.Button value="processed">Đã xử lý (0)</Radio.Button>
          </SubTabs>
        )}
      </TabsContainer> */}

      <FilterContainer>
        <SearchGroup>
          <Select
            value={searchType}
            onChange={handleSearchTypeChange}
            style={{ width: 140 }}
            className="search-select"
          >
            <Select.Option value="id">Mã đơn hàng</Select.Option>
            <Select.Option value="date">Ngày tạo</Select.Option>
          </Select>

          {searchType === "date" ? (
            <RangePicker
              value={dateRange}
              onChange={handleDateRangeChange}
              style={{ width: 280 }}
              placeholder={["Từ ngày", "Đến ngày"]}
              format="DD/MM/YYYY"
            />
          ) : (
            <Input.Search
              placeholder={searchPlaceholders[searchType]}
              value={searchValue}
              onChange={handleSearchValueChange}
              onSearch={handleApplySearch}
            />
          )}

          <ActionButtons>
            <Button
              type="primary"
              style={{ backgroundColor: "#67AE3E", borderColor: "#67AE3E" }}
              onClick={handleApplySearch}
            >
              Áp dụng
            </Button>
            <Button
              onClick={() => {
                resetFilters();
                setSearchValue("");
                setDateRange(null);
                setSearchType("id");
              }}
            >
              Đặt lại
            </Button>
          </ActionButtons>
        </SearchGroup>
      </FilterContainer>

      <OrderTable
        pageId={PAGE_ID}
        filters={filters}
        buildQueryParams={buildQueryParams}
        updatePagination={updatePagination}
        onStatusCountsUpdate={setStatusCounts}
      />
    </StyledCard>
  );
}
