import React, { useCallback, useEffect, useRef, useState } from "react";
import {
  Alert,
  AutoComplete,
  Button,
  Empty,
  Input,
  Pagination,
  Spin,
  Tag,
  Typography,
} from "antd";
import { useHistory, useLocation } from "react-router-dom";
import {
  ApartmentOutlined,
  ArrowLeftOutlined,
  CheckCircleOutlined,
  DragOutlined,
  DownOutlined,
  FullscreenOutlined,
  MailOutlined,
  MinusOutlined,
  PlusOutlined,
  RightOutlined,
  SearchOutlined,
  TeamOutlined,
  UserOutlined,
} from "@ant-design/icons";
import request from "@src/util/request";
import "./ReferalTree.css";

const ROOT_PAGE_SIZE = 20;
const CHILD_PAGE_SIZE = 20;
const MIN_ZOOM = 0.5;
const MAX_ZOOM = 2;
const clampZoom = (value: number) =>
  Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, Math.round(value * 1000) / 1000));

interface ReferralNode {
  id: number;
  name: string | null;
  email: string | null;
  inviteCode: string;
  salesRevenue: number | null;
  groupRevenue: number;
  isActive: boolean;
  directChildrenCount: number;
  downlineCount: number;
  activeDownlineCount: number;
  totalLevels: number;
}

interface TreePage {
  items: ReferralNode[];
  total: number;
  skip: number;
  limit: number;
  summary?: {
    totalMembers: number;
    totalRoots: number;
    activeMembers: number;
  };
}

interface ChildState {
  items: ReferralNode[];
  total: number;
  skip: number;
  loaded: boolean;
  loading: boolean;
  error: string | null;
}

interface TreeSearchItem {
  id: number;
  name: string | null;
  phone: string | null;
  email: string | null;
  rootId: number;
  path: Array<{ id: number; siblingPosition: number }>;
}

type ApiResponse = { code: number; message: string; data?: TreePage };
type SearchResponse = {
  code: number;
  message: string;
  data?: { items: TreeSearchItem[] };
};
const formatNumber = (value: number) => value.toLocaleString("vi-VN");
const formatRevenue = (value: number | null | undefined) =>
  value === null || value === undefined ? "—" : `${formatNumber(value)} đ`;

async function getTreePage(
  skip: number,
  limit: number,
  parentId?: number,
  rootId?: number
) {
  const response = await request<ApiResponse>({
    url: "/admin/referral/tree",
    options: {
      method: "get",
      params: {
        skip,
        limit,
        ...(parentId === undefined ? {} : { parentId }),
        ...(rootId === undefined ? {} : { rootId }),
      },
    },
  });
  if (
    response?.status !== 200 ||
    response.data.code !== 0 ||
    !response.data.data
  ) {
    throw new Error(response?.data?.message || "Không thể tải cây giới thiệu");
  }
  return response.data.data;
}

async function searchTree(search: string): Promise<TreeSearchItem[]> {
  const response = await request<SearchResponse>({
    url: "/admin/referral/search",
    options: { method: "get", params: { search } },
  });
  if (response?.status !== 200 || response.data.code !== 0) {
    throw new Error(response?.data?.message || "Không thể tìm thành viên");
  }
  return response.data.data?.items || [];
}

type PersonCardProps = {
  node: ReferralNode;
  depth: number;
  expanded: boolean;
  focused: boolean;
  onToggle?: () => void;
};

function PersonCard({
  node,
  depth,
  expanded,
  focused,
  onToggle,
}: PersonCardProps) {
  return (
    <article
      className={`referral-node-card ${
        depth === 0 ? "is-root" : depth === 1 ? "is-first-level" : ""
      } ${focused ? "is-search-target" : ""}`}
      data-referral-node-id={node.id}
    >
      <div className="referral-node-heading">
        <span className="referral-node-avatar" aria-hidden="true">
          <UserOutlined />
        </span>
        <span className="referral-node-title">
          <strong title={node.name || undefined}>
            {node.name?.trim() || "Chưa có tên"}
          </strong>
          <small>{depth === 0 ? "Gốc cây" : `Tầng ${depth + 1}`}</small>
        </span>
      </div>
      {node.email && (
        <span className="referral-node-email" title={node.email}>
          <MailOutlined aria-hidden="true" /> {node.email}
        </span>
      )}
      <div className="referral-node-revenue">
        <span>Doanh số nhóm</span>
        <strong>{formatRevenue(node.groupRevenue)}</strong>
      </div>
      <div className="referral-node-footer">
        <Tag color={node.isActive ? "green" : "default"}>
          {node.isActive ? "Hoạt động" : "Ngừng hoạt động"}
        </Tag>
        <span>{formatNumber(node.directChildrenCount)} F1</span>
      </div>
      {onToggle && node.directChildrenCount > 0 && (
        <button
          type="button"
          className="referral-node-toggle"
          onClick={onToggle}
          aria-expanded={expanded}
          aria-label={`${expanded ? "Thu gọn" : "Xem tuyến dưới"} của ${
            node.name || node.email || `ID ${node.id}`
          }`}
        >
          {expanded ? "Thu gọn" : "Xem tuyến dưới"}{" "}
          {expanded ? (
            <DownOutlined aria-hidden="true" />
          ) : (
            <RightOutlined aria-hidden="true" />
          )}
        </button>
      )}
    </article>
  );
}

type TreeNodeProps = {
  node: ReferralNode;
  depth: number;
  expandedIds: Set<number>;
  focusedId: number | null;
  childrenById: Record<number, ChildState>;
  onToggle: (node: ReferralNode) => void;
  onPageChange: (parentId: number, page: number) => void;
  onRetry: (parentId: number, skip: number) => void;
};

function TreeNode({
  node,
  depth,
  expandedIds,
  focusedId,
  childrenById,
  onToggle,
  onPageChange,
  onRetry,
}: TreeNodeProps) {
  const expanded = expandedIds.has(node.id);
  const children = childrenById[node.id];
  return (
    <div className="referral-tree-branch">
      <PersonCard
        node={node}
        depth={depth}
        expanded={expanded}
        focused={focusedId === node.id}
        onToggle={() => onToggle(node)}
      />
      {expanded && node.directChildrenCount > 0 && (
        <div className="referral-tree-descendants">
          {(!children || children.loading) && (
            <div className="referral-tree-feedback">
              <Spin tip="Đang tải tuyến dưới..." />
            </div>
          )}
          {children?.error && (
            <Alert
              type="error"
              showIcon
              message={children.error}
              action={
                <Button
                  size="small"
                  onClick={() => onRetry(node.id, children.skip)}
                >
                  Thử lại
                </Button>
              }
            />
          )}
          {children?.loaded && (
            <>
              <div className="referral-tree-children">
                {children.items.map((child) => (
                  <TreeNode
                    key={child.id}
                    node={child}
                    depth={depth + 1}
                    expandedIds={expandedIds}
                    focusedId={focusedId}
                    childrenById={childrenById}
                    onToggle={onToggle}
                    onPageChange={onPageChange}
                    onRetry={onRetry}
                  />
                ))}
              </div>
              {children.total > CHILD_PAGE_SIZE && (
                <Pagination
                  className="referral-tree-pagination"
                  current={Math.floor(children.skip / CHILD_PAGE_SIZE) + 1}
                  pageSize={CHILD_PAGE_SIZE}
                  total={children.total}
                  showSizeChanger={false}
                  onChange={(page) => onPageChange(node.id, page)}
                />
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}

export default function ReferalTreeCtrl() {
  const history = useHistory();
  const location = useLocation();
  const rootIdQuery = new URLSearchParams(location.search).get("rootId");
  const rootId = rootIdQuery === null ? null : Number(rootIdQuery);
  const [roots, setRoots] = useState<ReferralNode[]>([]);
  const [rootTotal, setRootTotal] = useState(0);
  const [rootSummary, setRootSummary] = useState<TreePage["summary"]>();
  const [rootPage, setRootPage] = useState(1);
  const [loadingRoots, setLoadingRoots] = useState(false);
  const [rootError, setRootError] = useState<string | null>(null);
  const [selectedRoot, setSelectedRoot] = useState<ReferralNode | null>(null);
  const [loadingRoot, setLoadingRoot] = useState(false);
  const [detailError, setDetailError] = useState<string | null>(null);
  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());
  const [childrenById, setChildrenById] = useState<Record<number, ChildState>>(
    {}
  );
  const [searchText, setSearchText] = useState("");
  const [searchResults, setSearchResults] = useState<TreeSearchItem[]>([]);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);
  const [pendingFocus, setPendingFocus] = useState<TreeSearchItem | null>(null);
  const [focusedId, setFocusedId] = useState<number | null>(null);
  const [openingPath, setOpeningPath] = useState(false);
  const activeRootIdRef = useRef<number | null>(null);
  const treeGenerationRef = useRef(0);
  const rootsRequestedRef = useRef(false);
  const childRequestSequenceRef = useRef<Record<number, number>>({});
  const chartRef = useRef<HTMLDivElement>(null);
  const zoomRef = useRef(1);
  const dragRef = useRef<{
    pointerId: number;
    x: number;
    y: number;
    left: number;
    top: number;
  } | null>(null);
  const [zoom, setZoom] = useState(1);
  const [dragging, setDragging] = useState(false);

  const changeZoom = useCallback(
    (value: number, clientX?: number, clientY?: number) => {
      const view = chartRef.current;
      const next = clampZoom(value);
      const previous = zoomRef.current;
      if (!view || next === previous) return;
      const bounds = view.getBoundingClientRect();
      const x =
        clientX === undefined ? view.clientWidth / 2 : clientX - bounds.left;
      const y =
        clientY === undefined ? view.clientHeight / 2 : clientY - bounds.top;
      const left = view.scrollLeft;
      const top = view.scrollTop;
      zoomRef.current = next;
      setZoom(next);
      window.requestAnimationFrame(() => {
        if (chartRef.current !== view) return;
        const ratio = next / previous;
        view.scrollLeft = (left + x) * ratio - x;
        view.scrollTop = (top + y) * ratio - y;
      });
    },
    []
  );

  const selectedRootId = selectedRoot?.id;
  useEffect(() => {
    const view = chartRef.current;
    if (!view) return;
    const onWheel = (event: WheelEvent) => {
      event.preventDefault();
      changeZoom(
        zoomRef.current * Math.exp(-event.deltaY * 0.0015),
        event.clientX,
        event.clientY
      );
    };
    view.addEventListener("wheel", onWheel, { passive: false });
    return () => view.removeEventListener("wheel", onWheel);
  }, [selectedRootId, changeZoom]);

  const startPan = (event: React.PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || !event.isPrimary) return;
    if (
      (event.target as HTMLElement).closest(
        "button, a, input, select, textarea, [role='button']"
      )
    )
      return;
    const view = event.currentTarget;
    dragRef.current = {
      pointerId: event.pointerId,
      x: event.clientX,
      y: event.clientY,
      left: view.scrollLeft,
      top: view.scrollTop,
    };
    view.setPointerCapture(event.pointerId);
    setDragging(true);
    event.preventDefault();
  };

  const movePan = (event: React.PointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    event.currentTarget.scrollLeft = drag.left - (event.clientX - drag.x);
    event.currentTarget.scrollTop = drag.top - (event.clientY - drag.y);
  };

  const endPan = (event: React.PointerEvent<HTMLDivElement>) => {
    if (dragRef.current?.pointerId !== event.pointerId) return;
    dragRef.current = null;
    setDragging(false);
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  };

  useEffect(() => {
    const query = searchText.trim();
    if (query.length < 2) {
      setSearchResults([]);
      setSearchError(null);
      setSearching(false);
      return;
    }
    let cancelled = false;
    const timer = window.setTimeout(async () => {
      setSearching(true);
      setSearchError(null);
      try {
        const items = await searchTree(query);
        if (!cancelled) setSearchResults(items);
      } catch (error) {
        if (!cancelled) {
          setSearchResults([]);
          setSearchError(
            error instanceof Error ? error.message : "Không thể tìm thành viên"
          );
        }
      } finally {
        if (!cancelled) setSearching(false);
      }
    }, 250);
    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [searchText]);

  const loadRoots = useCallback(async (page: number) => {
    setLoadingRoots(true);
    setRootError(null);
    try {
      const data = await getTreePage(
        (page - 1) * ROOT_PAGE_SIZE,
        ROOT_PAGE_SIZE
      );
      setRoots(data.items);
      setRootTotal(data.total);
      setRootSummary(data.summary);
      setRootPage(page);
    } catch (error) {
      setRootError(
        error instanceof Error ? error.message : "Không thể tải danh sách gốc"
      );
    } finally {
      setLoadingRoots(false);
    }
  }, []);

  useEffect(() => {
    if (rootId === null && !rootsRequestedRef.current) {
      rootsRequestedRef.current = true;
      void loadRoots(1);
    }
  }, [rootId, loadRoots]);

  const loadChildren = useCallback(async (parentId: number, skip: number) => {
    const ownerRootId = activeRootIdRef.current;
    const ownerGeneration = treeGenerationRef.current;
    if (ownerRootId === null) return;
    const requestSequence =
      (childRequestSequenceRef.current[parentId] || 0) + 1;
    childRequestSequenceRef.current[parentId] = requestSequence;
    setChildrenById((previous) =>
      activeRootIdRef.current === ownerRootId &&
      treeGenerationRef.current === ownerGeneration
        ? {
            ...previous,
            [parentId]: {
              items: [],
              total: previous[parentId]?.total || 0,
              skip,
              loaded: false,
              loading: true,
              error: null,
            },
          }
        : previous
    );
    try {
      const data = await getTreePage(skip, CHILD_PAGE_SIZE, parentId);
      if (
        activeRootIdRef.current !== ownerRootId ||
        treeGenerationRef.current !== ownerGeneration ||
        childRequestSequenceRef.current[parentId] !== requestSequence
      )
        return;
      setChildrenById((previous) => {
        if (
          activeRootIdRef.current !== ownerRootId ||
          treeGenerationRef.current !== ownerGeneration ||
          childRequestSequenceRef.current[parentId] !== requestSequence
        )
          return previous;
        return {
          ...previous,
          [parentId]: {
            items: data.items,
            total: data.total,
            skip: data.skip,
            loaded: true,
            loading: false,
            error: null,
          },
        };
      });
    } catch (error) {
      if (
        activeRootIdRef.current !== ownerRootId ||
        treeGenerationRef.current !== ownerGeneration ||
        childRequestSequenceRef.current[parentId] !== requestSequence
      )
        return;
      setChildrenById((previous) =>
        activeRootIdRef.current === ownerRootId &&
        treeGenerationRef.current === ownerGeneration &&
        childRequestSequenceRef.current[parentId] === requestSequence
          ? {
              ...previous,
              [parentId]: {
                ...(previous[parentId] || {
                  items: [],
                  total: 0,
                  skip,
                  loaded: false,
                }),
                loading: false,
                error:
                  error instanceof Error
                    ? error.message
                    : "Không thể tải tuyến dưới",
              },
            }
          : previous
      );
    }
  }, []);

  useEffect(() => {
    treeGenerationRef.current += 1;
    childRequestSequenceRef.current = {};
    activeRootIdRef.current = rootId;
    if (rootId === null) {
      setSelectedRoot(null);
      setChildrenById({});
      setExpandedIds(new Set());
      setDetailError(null);
      return;
    }
    if (!Number.isSafeInteger(rootId) || rootId <= 0) {
      setSelectedRoot(null);
      setLoadingRoot(false);
      setDetailError("Mã gốc cây không hợp lệ");
      return;
    }
    let active = true;
    setSelectedRoot(null);
    setLoadingRoot(true);
    setDetailError(null);
    setChildrenById({});
    setExpandedIds(new Set());

    const showRoot = (root: ReferralNode) => {
      setSelectedRoot(root);
      setExpandedIds(new Set([root.id]));
      if (root.directChildrenCount > 0) void loadChildren(root.id, 0);
    };
    const cachedRoot = roots.find((root) => root.id === rootId);
    if (cachedRoot) {
      showRoot(cachedRoot);
      setLoadingRoot(false);
      return () => {
        active = false;
      };
    }

    void getTreePage(0, 1, undefined, rootId)
      .then((data) => {
        if (!active) return;
        const root = data.items[0];
        if (!root) throw new Error("Không tìm thấy gốc cây giới thiệu");
        if (root.id !== rootId)
          throw new Error("API trả về gốc cây khác với gốc đã chọn");
        showRoot(root);
      })
      .catch((error) => {
        if (active)
          setDetailError(
            error instanceof Error ? error.message : "Không thể tải gốc cây"
          );
      })
      .finally(() => {
        if (active) setLoadingRoot(false);
      });
    return () => {
      active = false;
    };
  }, [rootId, loadChildren, roots]);

  useEffect(() => {
    if (!pendingFocus || selectedRoot?.id !== pendingFocus.rootId) return;
    let cancelled = false;
    const generation = treeGenerationRef.current;
    const path = pendingFocus.path;
    setOpeningPath(true);
    setSearchError(null);

    void Promise.all(
      path.slice(1).map((step, index) => {
        const parentId = path[index].id;
        const skip =
          Math.floor(step.siblingPosition / CHILD_PAGE_SIZE) * CHILD_PAGE_SIZE;
        childRequestSequenceRef.current[parentId] =
          (childRequestSequenceRef.current[parentId] || 0) + 1;
        return getTreePage(skip, CHILD_PAGE_SIZE, parentId).then((page) => {
          if (!page.items.some((item) => item.id === step.id)) {
            throw new Error(
              "Vị trí cây đã thay đổi, vui lòng tìm lại thành viên"
            );
          }
          return { parentId, page };
        });
      })
    )
      .then((pages) => {
        if (cancelled || treeGenerationRef.current !== generation) return;
        setChildrenById((previous) => {
          const next = { ...previous };
          for (const { parentId, page } of pages) {
            next[parentId] = {
              items: page.items,
              total: page.total,
              skip: page.skip,
              loaded: true,
              loading: false,
              error: null,
            };
          }
          return next;
        });
        setExpandedIds(new Set(path.slice(0, -1).map((step) => step.id)));
        setFocusedId(pendingFocus.id);
        setPendingFocus(null);
        window.setTimeout(() => {
          chartRef.current
            ?.querySelector(`[data-referral-node-id="${pendingFocus.id}"]`)
            ?.scrollIntoView({
              behavior: window.matchMedia("(prefers-reduced-motion: reduce)")
                .matches
                ? "auto"
                : "smooth",
              block: "center",
              inline: "center",
            });
        }, 100);
      })
      .catch((error) => {
        if (!cancelled && treeGenerationRef.current === generation) {
          setSearchError(
            error instanceof Error
              ? error.message
              : "Không thể mở vị trí trong cây"
          );
          setPendingFocus(null);
        }
      })
      .finally(() => {
        if (!cancelled && treeGenerationRef.current === generation) {
          setOpeningPath(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [pendingFocus, selectedRoot]);

  const selectSearchResult = (id: number) => {
    const result = searchResults.find((item) => item.id === id);
    if (!result) return;
    setSearchText(result.name || result.phone || result.email || "");
    setFocusedId(null);
    setPendingFocus(result);
    if (rootId !== result.rootId) {
      const params = new URLSearchParams(location.search);
      params.set("rootId", String(result.rootId));
      history.push({ pathname: location.pathname, search: params.toString() });
    }
  };

  const selectRoot = (root: ReferralNode) => {
    setPendingFocus(null);
    setFocusedId(null);
    const params = new URLSearchParams(location.search);
    params.set("rootId", String(root.id));
    history.push({ pathname: location.pathname, search: params.toString() });
  };

  const showRootList = () => {
    setPendingFocus(null);
    setFocusedId(null);
    const params = new URLSearchParams(location.search);
    params.delete("rootId");
    history.push({ pathname: location.pathname, search: params.toString() });
  };

  const toggleBranch = (node: ReferralNode) => {
    setExpandedIds((previous) => {
      const next = new Set(previous);
      if (next.has(node.id)) next.delete(node.id);
      else next.add(node.id);
      return next;
    });
    if (
      !expandedIds.has(node.id) &&
      node.directChildrenCount > 0 &&
      !childrenById[node.id]?.loaded &&
      !childrenById[node.id]?.loading
    )
      void loadChildren(node.id, 0);
  };

  return (
    <main className="referral-tree-page">
      <header className="referral-tree-page-header">
        <span className="referral-tree-page-icon" aria-hidden="true">
          <ApartmentOutlined />
        </span>
        <div>
          <Typography.Title level={2}>
            {rootId === null ? "Cây giới thiệu" : "Chi tiết cây giới thiệu"}
          </Typography.Title>
          <Typography.Text type="secondary">
            {rootId === null
              ? "Chọn một gốc cây để xem các tuyến dưới."
              : "Mở từng nhánh để xem các tuyến dưới của gốc cây này."}
          </Typography.Text>
        </div>
        <Button
          type="primary"
          style={{ marginLeft: "auto" }}
          onClick={() => history.push("/referral-reparent")}
        >
          Sắp xếp cây
        </Button>
      </header>

      <div className="referral-tree-layout">
        {rootId === null ? (
          <div className="referral-roots-container">
            {/* KHỐI 1: THỐNG KÊ TỔNG QUAN */}
            <section
              className="referral-overview-grid"
              aria-label="Thống kê cây giới thiệu"
            >
              <div className="referral-overview-card is-primary">
                <div className="referral-overview-card-header">
                  <span className="referral-overview-card-label">Tổng CTV</span>
                  <span className="referral-overview-card-icon">
                    <TeamOutlined aria-hidden="true" />
                  </span>
                </div>
                <strong className="referral-overview-card-value">
                  {rootSummary ? formatNumber(rootSummary.totalMembers) : "—"}
                </strong>
              </div>

              <div className="referral-overview-card is-purple">
                <div className="referral-overview-card-header">
                  <span className="referral-overview-card-label">Gốc cây</span>
                  <span className="referral-overview-card-icon">
                    <ApartmentOutlined aria-hidden="true" />
                  </span>
                </div>
                <strong className="referral-overview-card-value">
                  {rootSummary ? formatNumber(rootSummary.totalRoots) : "—"}
                </strong>
              </div>

              <div className="referral-overview-card is-green">
                <div className="referral-overview-card-header">
                  <span className="referral-overview-card-label">
                    Đang hoạt động
                  </span>
                  <span className="referral-overview-card-icon">
                    <CheckCircleOutlined aria-hidden="true" />
                  </span>
                </div>
                <strong className="referral-overview-card-value">
                  {rootSummary ? formatNumber(rootSummary.activeMembers) : "—"}
                </strong>
              </div>
            </section>

            {/* KHỐI 2: DANH SÁCH DỮ LIỆU CTV */}
            <aside
              className="referral-roots-panel"
              aria-label="Danh sách gốc cây giới thiệu"
            >
              <div className="referral-roots-panel-header">
                <div className="referral-roots-panel-title">
                  <h3>Danh sách CTV gốc</h3>
                  <Tag className="referral-roots-count-tag">
                    {formatNumber(rootTotal)} tài khoản
                  </Tag>
                </div>
                <span className="referral-roots-panel-desc">
                  Chọn một gốc cây để xem chi tiết cây giới thiệu
                </span>
              </div>

              {rootError && (
                <Alert
                  type="error"
                  showIcon
                  message={rootError}
                  action={
                    <Button
                      size="small"
                      onClick={() => void loadRoots(rootPage)}
                    >
                      Thử lại
                    </Button>
                  }
                />
              )}
              <Spin spinning={loadingRoots}>
                <div className="referral-roots-list">
                  {roots.map((root) => {
                    const hasSales = (root.groupRevenue ?? 0) > 0;
                    return (
                      <button
                        key={root.id}
                        type="button"
                        className="referral-root-option"
                        onClick={() => selectRoot(root)}
                        aria-label={`Xem cây của ${
                          root.name?.trim() || root.email || `ID ${root.id}`
                        }, mã mời ${root.inviteCode}${
                          root.email ? `, email ${root.email}` : ""
                        }`}
                      >
                        <div className="referral-root-card-top">
                          <div className="referral-root-main-info">
                            <strong
                              className="referral-root-name"
                              title={root.name?.trim() || "Chưa có tên"}
                            >
                              {root.name?.trim() || "Chưa có tên"}
                            </strong>
                            <div className="referral-root-sub-info">
                              <span
                                className="referral-root-code"
                                title={`Mã mời: ${root.inviteCode}`}
                              >
                                {root.inviteCode}
                              </span>
                              {root.email && (
                                <span
                                  className="referral-root-email"
                                  title={root.email}
                                >
                                  <MailOutlined aria-hidden="true" />{" "}
                                  {root.email}
                                </span>
                              )}
                            </div>
                          </div>
                          <span
                            className="referral-root-action-icon"
                            aria-hidden="true"
                          >
                            <RightOutlined />
                          </span>
                        </div>

                        <div className="referral-root-metrics-bar">
                          <div className="referral-root-metric-item">
                            <span className="metric-label">Doanh số nhóm</span>
                            <span
                              className={`metric-value ${
                                hasSales ? "is-highlight" : ""
                              }`}
                            >
                              {formatRevenue(root.groupRevenue)}
                            </span>
                          </div>
                          <div className="metric-divider" />
                          <div className="referral-root-metric-item">
                            <span className="metric-label">F1 trực tiếp</span>
                            <span className="metric-value">
                              {formatNumber(root.directChildrenCount)} CTV
                            </span>
                          </div>
                        </div>
                      </button>
                    );
                  })}
                  {!loadingRoots && roots.length === 0 && !rootError && (
                    <Empty description="Chưa có cây giới thiệu" />
                  )}
                </div>
              </Spin>
              {rootTotal > ROOT_PAGE_SIZE && (
                <Pagination
                  className="referral-roots-pagination"
                  current={rootPage}
                  pageSize={ROOT_PAGE_SIZE}
                  total={rootTotal}
                  size="small"
                  showSizeChanger={false}
                  onChange={(page) => void loadRoots(page)}
                />
              )}
            </aside>
          </div>
        ) : (
          <section
            className="referral-detail-panel"
            aria-label="Chi tiết cây giới thiệu"
          >
            {!selectedRoot || selectedRoot.id !== rootId ? (
              <>
                <Button
                  type="link"
                  icon={<ArrowLeftOutlined />}
                  aria-label="Danh sách gốc"
                  className="referral-back-button"
                  onClick={showRootList}
                >
                  Danh sách gốc
                </Button>
                <div className="referral-tree-placeholder">
                  {loadingRoot ? (
                    <Spin tip="Đang tải cây giới thiệu" />
                  ) : (
                    <Alert
                      type="error"
                      showIcon
                      message={detailError || "Không tìm thấy gốc cây"}
                    />
                  )}
                </div>
              </>
            ) : (
              <>
                <div className="referral-detail-header">
                  <div>
                    <Button
                      type="link"
                      icon={<ArrowLeftOutlined />}
                      aria-label="Danh sách gốc"
                      className="referral-back-button"
                      onClick={showRootList}
                    >
                      Danh sách gốc
                    </Button>
                    <h2>{selectedRoot.name?.trim() || "Chưa có tên"}</h2>
                    <p>
                      {selectedRoot.email && `${selectedRoot.email} · `}Mã mời{" "}
                      {selectedRoot.inviteCode}
                    </p>
                  </div>
                  <Tag color={selectedRoot.isActive ? "green" : "default"}>
                    {selectedRoot.isActive
                      ? "Đang hoạt động"
                      : "Ngừng hoạt động"}
                  </Tag>
                </div>

                <div className="referral-stat-grid">
                  <div className="referral-stat is-blue">
                    <TeamOutlined aria-hidden="true" />
                    <span>Tổng tuyến dưới</span>
                    <strong>{formatNumber(selectedRoot.downlineCount)}</strong>
                    <small>Tất cả các tầng</small>
                  </div>
                  <div className="referral-stat is-green">
                    <CheckCircleOutlined aria-hidden="true" />
                    <span>Đang hoạt động</span>
                    <strong>
                      {formatNumber(selectedRoot.activeDownlineCount)}
                    </strong>
                    <small>Trong tuyến dưới</small>
                  </div>
                  <div className="referral-stat is-purple">
                    <ApartmentOutlined aria-hidden="true" />
                    <span>Số tầng</span>
                    <strong>{formatNumber(selectedRoot.totalLevels)}</strong>
                    <small>Bao gồm gốc cây</small>
                  </div>
                  <div className="referral-stat is-orange">
                    <UserOutlined aria-hidden="true" />
                    <span>F1 trực tiếp</span>
                    <strong>
                      {formatNumber(selectedRoot.directChildrenCount)}
                    </strong>
                    <small>Nhánh đầu tiên</small>
                  </div>
                </div>

                {/* <div className="referral-chart-heading">
                  <div>
                    <h3>Tuyến giới thiệu</h3>
                  </div>
                  <span>Mở từng node để xem cấp tiếp theo</span>
                </div> */}
                <div className="referral-tree-search">
                  <AutoComplete
                    value={searchText}
                    options={searchResults.map((item) => ({
                      value: String(item.id),
                      label: (
                        <span className="referral-tree-search-option">
                          <strong>{item.name || `ID ${item.id}`}</strong>
                          <small>
                            {[`ID ${item.id}`, item.phone, item.email]
                              .filter(Boolean)
                              .join(" · ")}
                          </small>
                        </span>
                      ),
                    }))}
                    onSearch={setSearchText}
                    onSelect={(value) => selectSearchResult(Number(value))}
                    filterOption={false}
                    notFoundContent={
                      searching ? (
                        <Spin size="small" />
                      ) : searchText.trim().length >= 2 ? (
                        "Không tìm thấy thành viên trong cây"
                      ) : (
                        "Nhập ít nhất 2 ký tự"
                      )
                    }
                    className="referral-tree-search-input"
                  >
                    <Input
                      prefix={<SearchOutlined aria-hidden="true" />}
                      aria-label="Tìm thành viên theo số điện thoại, tên hoặc email"
                      placeholder="Tìm SĐT, tên hoặc email trong cây"
                    />
                  </AutoComplete>
                  {openingPath && <Spin size="small" tip="Đang mở vị trí..." />}
                </div>
                {searchError && (
                  <Alert
                    type="error"
                    showIcon
                    message={searchError}
                    style={{ marginBottom: 12 }}
                  />
                )}
                <div className="referral-chart-shell">
                  <div
                    className="referral-chart-toolbar"
                    aria-label="Điều khiển sơ đồ"
                  >
                    <Button
                      icon={<PlusOutlined />}
                      aria-label="Phóng to sơ đồ"
                      title="Phóng to"
                      onClick={() => changeZoom(zoomRef.current + 0.15)}
                      disabled={zoom >= MAX_ZOOM}
                    />
                    <span
                      className="referral-chart-zoom-value"
                      aria-live="polite"
                    >
                      {Math.round(zoom * 100)}%
                    </span>
                    <Button
                      icon={<MinusOutlined />}
                      aria-label="Thu nhỏ sơ đồ"
                      title="Thu nhỏ"
                      onClick={() => changeZoom(zoomRef.current - 0.15)}
                      disabled={zoom <= MIN_ZOOM}
                    />
                    <Button
                      icon={<FullscreenOutlined />}
                      aria-label="Đặt lại mức phóng 100%"
                      title="Đặt lại 100%"
                      onClick={() => changeZoom(1)}
                    />
                  </div>
                  <div className="referral-chart-hint">
                    <DragOutlined aria-hidden="true" /> Kéo để di chuyển · Lăn
                    chuột để phóng to, thu nhỏ
                  </div>
                  <div
                    className={`referral-chart-scroll${
                      dragging ? " is-dragging" : ""
                    }`}
                    ref={chartRef}
                    tabIndex={0}
                    aria-label="Sơ đồ cây giới thiệu. Dùng phím mũi tên để di chuyển, dấu cộng hoặc trừ để thu phóng."
                    onPointerDown={startPan}
                    onPointerMove={movePan}
                    onPointerUp={endPan}
                    onPointerCancel={endPan}
                    onKeyDown={(event) => {
                      if (event.target !== event.currentTarget) return;
                      const view = event.currentTarget;
                      if (event.key === "+" || event.key === "=")
                        changeZoom(zoomRef.current + 0.15);
                      else if (event.key === "-")
                        changeZoom(zoomRef.current - 0.15);
                      else if (event.key === "0") changeZoom(1);
                      else if (event.key === "ArrowLeft")
                        view.scrollLeft -= 100;
                      else if (event.key === "ArrowRight")
                        view.scrollLeft += 100;
                      else if (event.key === "ArrowUp") view.scrollTop -= 100;
                      else if (event.key === "ArrowDown") view.scrollTop += 100;
                      else return;
                      event.preventDefault();
                    }}
                  >
                    <div className="referral-chart-canvas" style={{ zoom }}>
                      <TreeNode
                        node={selectedRoot}
                        depth={0}
                        expandedIds={expandedIds}
                        focusedId={focusedId}
                        childrenById={childrenById}
                        onToggle={toggleBranch}
                        onPageChange={(parentId, page) =>
                          void loadChildren(
                            parentId,
                            (page - 1) * CHILD_PAGE_SIZE
                          )
                        }
                        onRetry={(parentId, skip) =>
                          void loadChildren(parentId, skip)
                        }
                      />
                    </div>
                  </div>
                </div>
              </>
            )}
          </section>
        )}
      </div>
    </main>
  );
}
