import React, { useEffect, useRef, useState } from "react";
import {
  Alert,
  AutoComplete,
  Button,
  Card,
  Col,
  Input,
  message,
  Modal,
  Row,
  Space,
  Spin,
  Typography,
} from "antd";
import {
  ArrowLeftOutlined,
  ArrowRightOutlined,
  DeleteOutlined,
  PlusOutlined,
  SearchOutlined,
} from "@ant-design/icons";
import { useHistory } from "react-router-dom";
import request from "@src/util/request";

interface Member {
  id: number;
  name: string | null;
  phone: string | null;
  email: string | null;
  parent: {
    id: number;
    name: string | null;
    phone: string | null;
    email: string | null;
  } | null;
  rootId: number;
  path: Array<{ id: number; siblingPosition: number }>;
}

interface MoveRow {
  key: number;
  source: Member | null;
  target: Member | null;
}

interface MoveResult {
  customerId: number;
  previousReferrerCustomerId: number | null;
  referrerCustomerId: number;
  changed: boolean;
  downlineCount: number;
}

interface SearchResponse {
  code: number;
  message: string;
  data?: { items: Member[] };
}

interface MoveResponse {
  code: number;
  message: string;
  data?: { dryRun: boolean; changes: MoveResult[] };
}

const newRow = (key: number): MoveRow => ({ key, source: null, target: null });
const memberLabel = (member: Member) =>
  member.name?.trim() || member.email || member.phone || "Khách hàng";
const memberDetails = (member: Member) =>
  [member.phone, member.email].filter(Boolean).join(" · ") ||
  "Chưa có số điện thoại hoặc email";
const memberSummary = (member: Pick<Member, "name" | "phone" | "email">) =>
  [
    ...new Set(
      [member.name?.trim(), member.phone, member.email].filter(Boolean),
    ),
  ].join(" · ") || "Chưa có thông tin liên hệ";
const parentId = (member: Member) =>
  member.path.length > 1 ? member.path[member.path.length - 2].id : null;
const currentParentLabel = (member: Member) =>
  member.parent ? memberSummary(member.parent) : "gốc cây";

function MemberSelect({
  label,
  value,
  onChange,
}: {
  label: string;
  value: Member | null;
  onChange: (member: Member | null) => void;
}) {
  const [text, setText] = useState("");
  const [results, setResults] = useState<Member[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    setText(value ? memberSummary(value) : "");
  }, [value]);

  useEffect(() => {
    const query = text.trim();
    if (value || query.length < 2) {
      setResults([]);
      setLoading(false);
      setError("");
      return;
    }
    let cancelled = false;
    const timer = window.setTimeout(async () => {
      setLoading(true);
      setError("");
      try {
        const response = await request<SearchResponse>({
          url: "/admin/referral/search",
          options: { method: "get", params: { search: query } },
        });
        if (response?.status !== 200 || response.data.code !== 0) {
          throw new Error(
            response?.data?.message || "Không thể tìm thành viên",
          );
        }
        if (!cancelled) setResults(response.data.data?.items || []);
      } catch (cause: any) {
        if (!cancelled) {
          setResults([]);
          setError(cause?.message || "Không thể tìm thành viên");
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }, 250);
    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [text, value]);

  return (
    <div>
      <Typography.Text strong>{label}</Typography.Text>
      <AutoComplete
        style={{ width: "100%", marginTop: 8 }}
        value={text}
        options={results.map((member) => ({
          value: String(member.id),
          label: (
            <span>
              <strong>{memberLabel(member)}</strong>
              <br />
              <small>{memberDetails(member)}</small>
            </span>
          ),
        }))}
        filterOption={false}
        onSearch={(next) => {
          setText(next);
          if (value) onChange(null);
        }}
        onSelect={(id) => {
          const selected = results.find((item) => item.id === Number(id));
          if (selected) onChange(selected);
        }}
        notFoundContent={
          loading ? <Spin size="small" /> : error || "Không tìm thấy"
        }
      >
        <Input
          prefix={<SearchOutlined />}
          placeholder="Tìm theo tên, SĐT hoặc email"
          aria-label={label}
        />
      </AutoComplete>
      {value && label === "Người/nhánh cần chuyển" && (
        <Typography.Text
          type="secondary"
          style={{ display: "block", marginTop: 6 }}
        >
          {`Cha hiện tại: ${currentParentLabel(value)}`}
        </Typography.Text>
      )}
    </div>
  );
}

export default function ReferralReparentCtrl() {
  const history = useHistory();
  const nextKey = useRef(2);
  const savingRef = useRef(false);
  const [rows, setRows] = useState<MoveRow[]>([newRow(1)]);
  const [preview, setPreview] = useState<MoveResult[] | null>(null);
  const [checking, setChecking] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const updateRow = (
    key: number,
    field: "source" | "target",
    member: Member | null,
  ) => {
    setRows((current) =>
      current.map((row) =>
        row.key === key ? { ...row, [field]: member } : row,
      ),
    );
    setPreview(null);
    setError("");
  };

  const changes = () => {
    if (rows.some((row) => !row.source || !row.target)) {
      throw new Error("Chọn đủ người cần chuyển và cha mới cho từng dòng.");
    }
    if (rows.some((row) => row.source!.id === row.target!.id)) {
      throw new Error("Một người không thể là cha của chính mình.");
    }
    const sourceIds = rows.map((row) => row.source!.id);
    if (new Set(sourceIds).size !== sourceIds.length) {
      throw new Error("Mỗi người cần chuyển chỉ được xuất hiện một lần.");
    }
    return rows.map((row) => ({
      customerId: row.source!.id,
      referrerCustomerId: row.target!.id,
      expectedReferrerCustomerId: parentId(row.source!),
    }));
  };

  const submit = async (dryRun: boolean) => {
    const selected = changes();
    const response = await request<MoveResponse>({
      url: "/admin/referral/reparent",
      options: {
        method: "put",
        data: {
          changes: selected,
          reason: "Điều chỉnh cây qua CMS",
          dryRun,
        },
      },
    });
    if (
      response?.status !== 200 ||
      response.data.code !== 0 ||
      !response.data.data
    ) {
      throw new Error(
        response?.data?.message || "Không thể cập nhật cây giới thiệu.",
      );
    }
    return response.data.data.changes;
  };

  const check = async () => {
    setChecking(true);
    setPreview(null);
    setError("");
    try {
      setPreview(await submit(true));
    } catch (cause: any) {
      setError(cause?.message || "Không thể xem trước thay đổi.");
    } finally {
      setChecking(false);
    }
  };

  const save = () => {
    if (!preview || savingRef.current) return;
    Modal.confirm({
      title: "Xác nhận chuyển các nhánh?",
      content: `Áp dụng ${
        preview.filter((item) => item.changed).length
      } thay đổi cùng lúc. Các tuyến dưới đi theo người được chuyển.`,
      okText: "Xác nhận chuyển",
      cancelText: "Xem lại",
      onOk: async () => {
        if (savingRef.current) return;
        savingRef.current = true;
        setSaving(true);
        setError("");
        try {
          const result = await submit(false);
          message.success(
            `Đã cập nhật ${
              result.filter((item) => item.changed).length
            } nhánh.`,
          );
          setRows([newRow(nextKey.current++)]);
          setPreview(null);
        } catch (cause: any) {
          setPreview(null);
          setError(cause?.message || "Không thể cập nhật cây giới thiệu.");
          throw cause;
        } finally {
          setSaving(false);
          savingRef.current = false;
        }
      },
    });
  };

  const overlapping = rows.some((row, index) =>
    rows.some(
      (other, otherIndex) =>
        index !== otherIndex &&
        !!row.source &&
        !!other.source &&
        other.source.path.some((step) => step.id === row.source!.id),
    ),
  );

  return (
    <main
      style={{ maxWidth: 1200, margin: "0 auto", padding: "24px 16px 48px" }}
    >
      <Space style={{ marginBottom: 16 }}>
        <Button onClick={() => history.goBack()}>
          <ArrowLeftOutlined />
          Quay lại cây
        </Button>
      </Space>
      <Typography.Title level={2}>Sắp xếp cây giới thiệu</Typography.Title>
      <Alert
        type="info"
        showIcon
        message="Mỗi dòng chuyển một người cùng toàn bộ tuyến dưới sang cha mới. Các dòng được kiểm tra và lưu cùng một lần."
        style={{ marginBottom: 20 }}
      />
      {rows.map((row, index) => (
        <Card
          key={row.key}
          title={`Lượt chuyển ${index + 1}`}
          style={{ marginBottom: 16 }}
          extra={
            <Button
              aria-label={`Xóa lượt chuyển ${index + 1}`}
              icon={<DeleteOutlined />}
              disabled={rows.length === 1 || checking || saving}
              onClick={() => {
                setRows((current) =>
                  current.filter((item) => item.key !== row.key),
                );
                setPreview(null);
              }}
            />
          }
        >
          <Row gutter={[16, 16]} align="middle">
            <Col xs={24} md={11}>
              <MemberSelect
                label="Người/nhánh cần chuyển"
                value={row.source}
                onChange={(member) => updateRow(row.key, "source", member)}
              />
            </Col>
            <Col xs={24} md={2} style={{ textAlign: "center" }}>
              <ArrowRightOutlined aria-hidden="true" />
            </Col>
            <Col xs={24} md={11}>
              <MemberSelect
                label="Chuyển xuống dưới"
                value={row.target}
                onChange={(member) => updateRow(row.key, "target", member)}
              />
            </Col>
          </Row>
        </Card>
      ))}
      <Button
        icon={<PlusOutlined />}
        disabled={rows.length >= 50 || checking || saving}
        onClick={() => {
          setRows((current) => [...current, newRow(nextKey.current++)]);
          setPreview(null);
        }}
        style={{ marginBottom: 24 }}
      >
        Thêm lượt chuyển
      </Button>
      {overlapping && (
        <Alert
          type="warning"
          showIcon
          message="Có các nhánh được chọn nằm trong nhau. Hãy xem kỹ kết quả cuối trước khi xác nhận."
          style={{ marginBottom: 20 }}
        />
      )}
      <Card title="Kiểm tra và xác nhận" style={{ marginBottom: 20 }}>
        {error && (
          <Alert
            type="error"
            showIcon
            message={error}
            style={{ marginBottom: 16 }}
          />
        )}
        <Space>
          <Button
            loading={checking}
            disabled={saving}
            onClick={() => void check()}
          >
            Xem trước toàn bộ
          </Button>
          <Button
            type="primary"
            loading={saving}
            disabled={
              !preview || checking || !preview.some((item) => item.changed)
            }
            onClick={save}
          >
            Xác nhận chuyển
          </Button>
        </Space>
        {preview && (
          <div
            style={{
              borderTop: "1px solid #f0f0f0",
              marginTop: 20,
              paddingTop: 16,
            }}
          >
            <Typography.Text
              strong
              style={{ display: "block", marginBottom: 12 }}
            >
              Kết quả xem trước
            </Typography.Text>
            {preview.map((item, index) => {
              const source = rows.find(
                (row) => row.source?.id === item.customerId,
              )?.source;
              const target = rows.find(
                (row) => row.target?.id === item.referrerCustomerId,
              )?.target;
              return (
                <Typography.Paragraph
                  key={item.customerId}
                  style={{ marginBottom: 12 }}
                >
                  <strong>
                    {index + 1}. {source ? memberLabel(source) : "Khách hàng"}
                  </strong>
                  {` · ${item.downlineCount} người tuyến dưới: `}
                  {`cha ${source ? currentParentLabel(source) : "không rõ"} → `}
                  <strong>{target ? memberLabel(target) : "Khách hàng"}</strong>
                  {item.changed ? "" : " · Không thay đổi"}
                </Typography.Paragraph>
              );
            })}
          </div>
        )}
      </Card>
    </main>
  );
}
