import { Component } from 'react';
import { Input } from 'antd';
import axios from 'axios';

class UploadV2 extends Component<
  {
    schema: Record<string, any>;
    disabled?: boolean;
    invalid?: boolean;
    value: any;
    onChange?: (val: any) => void;
  },
  any
> {
  constructor(props: any) {
    super(props);
    this.state = {
      progress: 0,
      uploading: false,
    };
  }

  uploadFile = async (file: File) => {
    try {
      if (file.size > 20 * 1024 * 1024) {
        throw new Error("Giới hạn kích thước file là 20MB");
      }

      const token = localStorage.getItem('token');
      if (!token) return
      const fileName = `${Date.now()}_${file.name}`;

      // Init upload
      const initRes = await axios.post(
        `file/upload-file-large/get-multipart-upload-id`,
        { fileName },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      const uploadId = initRes.data?.UploadId;
      if (!uploadId) throw new Error("Không lấy được UploadId");

      const chunks = this.createChunks(file);
      let uploadedSize = 0;

      this.setState({ uploading: true, progress: 0 });

      // Upload từng chunk
      const uploadPromises = chunks.map((chunk, index) =>
        this.uploadChunk(chunk, index + 1, uploadId, token).then(() => {
          uploadedSize += chunk.size;
          const percent = Math.min(
            Math.floor((uploadedSize / file.size) * 100),
            99
          );
          this.setState({ progress: percent });
        })
      );

      await Promise.all(uploadPromises);

      // Complete upload
      const completeRes = await axios.post(
        `file/upload-file-large/complete-upload`,
        { uploadId },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      const uploaded = completeRes.data?.created?.[0];
      if (!uploaded?.url) throw new Error("Upload lỗi");

      this.setState({ progress: 100, uploading: false });

      if (this.props.onChange) {
        this.props.onChange(uploaded.url);
      }
    } catch (err: any) {
      console.error(err);
      alert(err.message);
      this.setState({ uploading: false });
    }
  };

  uploadChunk = async (
    chunk: Blob,
    partNumber: number,
    uploadId: string,
    token: string
  ) => {
    const formData = new FormData();
    formData.append('file', chunk);

    return axios.put(`file/upload-file-large/upload-part`, formData, {
      headers: { Authorization: `Bearer ${token}` },
      params: {
        index: partNumber,
        uploadId,
      },
    });
  };

  createChunks = (file: File) => {
    const chunkSize = 5 * 1024 * 1024;
    const chunks = [];
    for (let i = 0; i < file.size; i += chunkSize) {
      chunks.push(file.slice(i, i + chunkSize));
    }
    return chunks;
  };

  render() {
    const { progress, uploading } = this.state;
    return (
      <div>
        <Input
          type="file"
          disabled={this.props.disabled}
          onChange={(evt: any) => {
            this.uploadFile(evt.target.files[0]);
          }}
        />
        {uploading && <div>Đang upload: {progress}%</div>}
        {this.props.value && (
          <div>
            Đã có file:{" "}
            <a href={this.props.value} target="_blank" rel="noreferrer">
              {this.props.value}
            </a>
          </div>
        )}
      </div>
    );
  }
}

export default UploadV2;