import React, { useContext } from 'react';
import { ConfigProvider } from 'antd';
import zhCN from '../../locale/zh_CN';
import enUS from '../../locale/en_US';
import viVN from '../../locale/vi_VN';
import itIT from '../../locale/it_IT';
import jaJP from '../../locale/ja_JP';
import esES from '../../locale/es_ES';
import ruRU from '../../locale/ru_RU';
import msMY from '../../locale/ms_MY';
import zhTW from '../../locale/zh_TW';

export interface IntlType {
  locale: string;
  getMessage: (id: string, defaultMessage: string) => string;
}

// eslint-disable-next-line @typescript-eslint/ban-types
function get(
  source: object,
  path: string,
  defaultValue?: string
): string | undefined {
  // a[3].b -> a.3.b
  const paths = path.replace(/\[(\d+)\]/g, '.$1').split('.');
  let result = source;
  let message = defaultValue;
  // eslint-disable-next-line no-restricted-syntax
  for (const p of paths) {
    message = Object(result)[p];
    result = Object(result)[p];
    if (message === undefined) {
      return defaultValue;
    }
  }
  return message;
}

/**
 * 创建一个操作函数
 * @param locale
 * @param localeMap
 */
const createIntl = (
  locale: string,
  localeMap: { [key: string]: any }
): IntlType => ({
  getMessage: (id: string, defaultMessage: string) =>
    get(localeMap, id, defaultMessage) || defaultMessage,
  locale,
});

const zhCNIntl = createIntl('zh_CN', zhCN);
const enUSIntl = createIntl('en_US', enUS);
const viVNIntl = createIntl('vi_VN', viVN);
const itITIntl = createIntl('it_IT', itIT);
const jaJPIntl = createIntl('ja_JP', jaJP);
const esESIntl = createIntl('es_ES', esES);
const ruRUIntl = createIntl('ru_RU', ruRU);
const msMYIntl = createIntl('ms_MY', msMY);
const zhTWIntl = createIntl('zh_TW', zhTW);

const intlMap: Record<string, any> = {
  'vi-VN': viVNIntl,
  'en-US': enUSIntl,
  'zh-CN': zhCNIntl,
  'it-IT': itITIntl,
  'js-JP': jaJPIntl,
  'es-ES': esESIntl,
  'ru-RU': ruRUIntl,
  'ms-MY': msMYIntl,
  'zh-TW': zhTWIntl,
  vi: viVNIntl,
  en: enUSIntl,
  zh: zhCNIntl,
  en_US: enUSIntl,
  vi_VN: viVNIntl,
};

export {
  enUSIntl,
  zhCNIntl,
  viVNIntl,
  itITIntl,
  jaJPIntl,
  esESIntl,
  ruRUIntl,
  msMYIntl,
  zhTWIntl,
};

const IntlContext = React.createContext<IntlType>(viVNIntl);

const { Consumer: IntlConsumer, Provider: IntlProvider } = IntlContext;

export { IntlConsumer, IntlProvider, createIntl };

export function useIntl(): IntlType {
  const antdContext = useContext(ConfigProvider.ConfigContext);
  const context = useContext(IntlContext);

  const rawLocale = antdContext?.locale;
  const antdLocale =
    rawLocale?.locale ||
    (rawLocale as any)?.default?.locale;

  if (antdLocale) {
    if (intlMap[antdLocale]) {
      return intlMap[antdLocale];
    }
    const normalized = antdLocale.replace('_', '-');
    if (intlMap[normalized]) {
      return intlMap[normalized];
    }
    if (antdLocale.startsWith('en')) {
      return enUSIntl;
    }
    if (antdLocale.startsWith('vi')) {
      return viVNIntl;
    }
    if (antdLocale.startsWith('zh')) {
      return zhCNIntl;
    }
  }

  if (context && (context as any).locale && (context as any).locale !== 'vi_VN') {
    return context;
  }

  if (typeof window !== 'undefined') {
    const currentLocale = window.localStorage.getItem('locale');
    if (currentLocale && intlMap[currentLocale]) {
      return intlMap[currentLocale];
    }
    if (currentLocale?.startsWith('en')) {
      return enUSIntl;
    }
    if (currentLocale?.startsWith('vi')) {
      return viVNIntl;
    }
    const umiLocale = window.localStorage.getItem('umi_locale');
    if (umiLocale && intlMap[umiLocale]) {
      return intlMap[umiLocale];
    }
  }

  return context || viVNIntl;
}

export default IntlContext;
