import React from 'react';
import { Button, Dropdown, Menu } from 'antd';
import { GlobalOutlined } from '@ant-design/icons';
import { connect } from 'dva';
import { StoreState } from '@src/interfaces';

interface LanguageSelectorProps {
  dispatch?: any;
  locale?: {
    languageId?: string;
    locale?: string;
    name?: string;
    icon?: string;
  };
}

const LanguageSelector: React.FC<LanguageSelectorProps> = ({ dispatch, locale }) => {
  const currentLocale = locale?.locale || 'vi';

  const handleLanguageChange = (lang: string) => {
    const target =
      lang === 'en'
        ? {
            languageId: 'english',
            locale: 'en',
            name: 'English',
            icon: 'us',
          }
        : {
            languageId: 'vietnam',
            locale: 'vi',
            name: 'Tiếng Việt',
            icon: 'vn',
          };

    if (dispatch) {
      dispatch({
        type: 'settings/switchLanguage',
        payload: target,
      });
    }

    if (typeof window !== 'undefined') {
      localStorage.setItem('locale', target.locale);
      localStorage.setItem('umi_locale', target.locale === 'vi' ? 'vi-VN' : 'en-US');
    }
  };

  const menu = (
    <Menu selectedKeys={[currentLocale]}>
      <Menu.Item key="vi" onClick={() => handleLanguageChange('vi')}>
        <span role="img" aria-label="Vietnam" style={{ marginRight: 8 }}>
          🇻🇳
        </span>
        Tiếng Việt
      </Menu.Item>
      <Menu.Item key="en" onClick={() => handleLanguageChange('en')}>
        <span role="img" aria-label="English" style={{ marginRight: 8 }}>
          🇺🇸
        </span>
        English
      </Menu.Item>
    </Menu>
  );

  return (
    <div className="gx-language-selector">
      <Dropdown overlay={menu} placement="bottomRight">
        <Button>
          <GlobalOutlined />
          {currentLocale === 'en' ? ' English' : ' Tiếng Việt'}
        </Button>
      </Dropdown>
    </div>
  );
};

const mapStateToProps = ({ settings }: StoreState) => {
  return {
    locale: settings.locale,
  };
};

export default connect(mapStateToProps)(LanguageSelector);