import React, { useEffect, useRef, useState } from "react";
import {
  Alert,
  Button,
  Card,
  Col,
  Form,
  InputNumber,
  Modal,
  Row,
  Space,
  Statistic,
  Table,
  Typography,
} from "antd";
import {
  DownloadOutlined,
  MinusOutlined,
  PlusOutlined,
  ReloadOutlined,
} from "@ant-design/icons";
import { saveAs } from "file-saver";
import moment from "moment";
import request from "@src/util/request";
import CustomerPicker, { CustomerItem } from "./CustomerPicker";

interface Props {
  pageInfo?: any;
}

interface FormValues {
  amount: number;
}

interface AdjustmentResponse {
  code: number;
  message: string;
  data?: {
    transactionId: string;
    customerId: number;
    amount: number;
    direction: "credit" | "debit";
  };
}

interface BalanceResponse {
  code: number;
  message: string;
  data?: {
    customerId: number;
    balance: number;
    reservedAmount: number;
    legacyPendingAmount: number;
    availableAmount: number;
  };
}

interface TransactionItem {
  id: string;
  type: string;
  direction: "credit" | "debit";
  content: string;
  amount: number;
  balanceAfter: number;
  calculationDate: string;
  createdAt: number;
}

interface TransactionsResponse {
  code: number;
  message: string;
  data?: {
    customerId: number;
    total: number;
    items: TransactionItem[];
  };
}

const HISTORY_PAGE_SIZE = 20;

const formatMoney = (amount: number) => `${amount.toLocaleString("vi-VN")} đ`;
const moneyFormatter = (value?: string | number) =>
  value === undefined || value === null || value === ""
    ? ""
    : `${String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ".")} đ`;
const moneyParser = (value?: string) => {
  const input = (value || "").trim();
  const digits = input.replace(/[^0-9]/g, "");
  if (!digits) return input.startsWith("-") ? "-" : "";
  return `${input.startsWith("-") ? "-" : ""}${digits}`;
};

export default function CommissionWalletAdjustmentCtrl({ pageInfo }: Props) {
  const [form] = Form.useForm<FormValues>();
  const [selectedCustomer, setSelectedCustomer] = useState<CustomerItem | null>(
    null
  );
  const [pickerOpen, setPickerOpen] = useState(false);
  const [selectionError, setSelectionError] = useState("");
  const [enteredAmount, setEnteredAmount] = useState<number | null>(null);
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false);
  const confirmingRef = useRef(false);
  const [error, setError] = useState("");
  const [saved, setSaved] = useState<{
    customer: CustomerItem;
    amount: number;
    transactionId: string;
  } | null>(null);
  const [balance, setBalance] = useState<BalanceResponse["data"] | null>(null);
  const [balanceLoading, setBalanceLoading] = useState(false);
  const [balanceError, setBalanceError] = useState("");
  const [balanceRefresh, setBalanceRefresh] = useState(0);
  const [transactions, setTransactions] = useState<TransactionItem[]>([]);
  const [historyTotal, setHistoryTotal] = useState(0);
  const [historyPage, setHistoryPage] = useState(1);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyError, setHistoryError] = useState("");
  const [historyRefresh, setHistoryRefresh] = useState(0);
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState("");
  const selectedCustomerId = selectedCustomer?.id;

  useEffect(() => {
    if (!selectedCustomerId) return;
    let cancelled = false;
    setBalance(null);
    setBalanceLoading(true);
    setBalanceError("");
    const loadBalance = async () => {
      try {
        const response = await request<BalanceResponse>({
          url: "/admin/commission-wallets/balance",
          options: {
            method: "get",
            params: { customerId: selectedCustomerId },
          },
        });
        if (cancelled) return;
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data
        ) {
          throw new Error(response?.data?.message || "Không thể tải số dư ví.");
        }
        setBalance(response.data.data);
      } catch (cause: any) {
        if (!cancelled) {
          setBalanceError(cause?.message || "Không thể tải số dư ví.");
        }
      } finally {
        if (!cancelled) setBalanceLoading(false);
      }
    };
    loadBalance();
    return () => {
      cancelled = true;
    };
  }, [selectedCustomerId, balanceRefresh]);

  useEffect(() => {
    if (!selectedCustomerId) return;
    let cancelled = false;
    setHistoryLoading(true);
    setHistoryError("");
    const loadHistory = async () => {
      try {
        const response = await request<TransactionsResponse>({
          url: "/admin/commission-wallets/transactions",
          options: {
            method: "get",
            params: {
              customerId: selectedCustomerId,
              skip: (historyPage - 1) * HISTORY_PAGE_SIZE,
              limit: HISTORY_PAGE_SIZE,
            },
          },
        });
        if (cancelled) return;
        if (
          response?.status !== 200 ||
          response.data?.code !== 0 ||
          !response.data.data ||
          !Array.isArray(response.data.data.items)
        ) {
          throw new Error(
            response?.data?.message || "Không thể tải lịch sử giao dịch."
          );
        }
        setTransactions(response.data.data.items);
        setHistoryTotal(response.data.data.total);
      } catch (cause: any) {
        if (cancelled) return;
        setTransactions([]);
        setHistoryTotal(0);
        setHistoryError(cause?.message || "Không thể tải lịch sử giao dịch.");
      } finally {
        if (!cancelled) setHistoryLoading(false);
      }
    };
    loadHistory();
    return () => {
      cancelled = true;
    };
  }, [selectedCustomerId, historyPage, historyRefresh]);

  const exportHistory = async () => {
    if (!selectedCustomerId || exporting) return;
    setExporting(true);
    setExportError("");
    try {
      const response = await request<Blob>({
        url: "/admin/commission-wallets/transactions/export",
        options: {
          method: "get",
          params: { customerId: selectedCustomerId },
          responseType: "blob",
        },
      });
      if (
        response?.status !== 200 ||
        !(response.data instanceof Blob) ||
        !response.data.type.includes("spreadsheetml.sheet") ||
        response.data.size === 0
      ) {
        throw new Error("Không thể xuất lịch sử giao dịch hoa hồng.");
      }
      saveAs(response.data, `lich-su-hoa-hong-${selectedCustomerId}.xlsx`);
    } catch (cause: any) {
      setExportError(
        cause?.message || "Không thể xuất lịch sử giao dịch hoa hồng."
      );
    } finally {
      setExporting(false);
    }
  };

  const submit = async (customer: CustomerItem, amount: number) => {
    if (savingRef.current) return;
    savingRef.current = true;
    setSaving(true);
    setError("");
    setSaved(null);
    try {
      const response = await request<AdjustmentResponse>({
        url: "/admin/commission-wallets/adjust-total",
        options: {
          method: "post",
          data: { customerId: customer.id, amount },
        },
      });
      if (
        response?.status !== 200 ||
        response.data?.code !== 0 ||
        !response.data.data?.transactionId
      ) {
        throw new Error(
          response?.data?.message || "Không thể điều chỉnh ví hoa hồng."
        );
      }
      setSaved({
        customer,
        amount,
        transactionId: response.data.data.transactionId,
      });
      setEnteredAmount(null);
      form.resetFields();
      setBalanceLoading(true);
      setBalanceRefresh((value) => value + 1);
      setHistoryPage(1);
      setHistoryRefresh((value) => value + 1);
    } catch (cause: any) {
      setError(
        `${
          cause?.message || "Không thể điều chỉnh ví hoa hồng."
        } Nếu kết nối bị gián đoạn, hãy kiểm tra giao dịch trước khi gửi lại để tránh cộng hoặc trừ hai lần.`
      );
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };

  const confirmSubmit = ({ amount }: FormValues) => {
    if (!selectedCustomer) {
      setSelectionError("Vui lòng chọn khách hàng cần điều chỉnh ví.");
      return;
    }
    if (savingRef.current || confirmingRef.current) return;
    const customer = selectedCustomer;
    confirmingRef.current = true;
    Modal.confirm({
      title: `${amount > 0 ? "Cộng" : "Trừ"} hoa hồng cho khách hàng?`,
      content: (
        <div>
          <div>
            Khách hàng: <strong>{customer.name || `#${customer.id}`}</strong>{" "}
            (ID {customer.id})
          </div>
          <div>
            Số tiền: <strong>{formatMoney(Math.abs(amount))}</strong>
          </div>
          <div>Thao tác sẽ ghi ngay một giao dịch vào ví hoa hồng.</div>
        </div>
      ),
      okText: amount > 0 ? "Xác nhận cộng" : "Xác nhận trừ",
      okButtonProps: { danger: amount < 0 },
      cancelText: "Hủy",
      onCancel: () => {
        confirmingRef.current = false;
      },
      onOk: async () => {
        try {
          await submit(customer, amount);
        } finally {
          confirmingRef.current = false;
        }
      },
    });
  };

  const historyColumns: any[] = [
    {
      title: "Thời gian",
      dataIndex: "createdAt",
      key: "createdAt",
      width: 175,
      render: (value: number) => moment(value).format("DD/MM/YYYY HH:mm"),
    },
    {
      title: "Nội dung",
      dataIndex: "content",
      key: "content",
      render: (value: string) => value || "Giao dịch hoa hồng",
    },
    {
      title: "Số tiền",
      dataIndex: "amount",
      key: "amount",
      align: "right",
      width: 180,
      render: (value: number, item: TransactionItem) => (
        <Typography.Text
          type={item.direction === "debit" ? "danger" : "success"}
        >
          {item.direction === "credit" ? "+" : "−"}
          {formatMoney(value)}
        </Typography.Text>
      ),
    },
    {
      title: "Số dư sau giao dịch",
      dataIndex: "balanceAfter",
      key: "balanceAfter",
      align: "right",
      width: 180,
      render: (value: number) => formatMoney(value),
    },
  ];

  return (
    <div style={{ maxWidth: 1320, margin: "0 auto", padding: "24px 16px" }}>
      <Typography.Title level={3} style={{ marginBottom: 24 }}>
        Điều chỉnh ví hoa hồng
      </Typography.Title>

      {error && (
        <Alert
          type="error"
          showIcon
          message="Chưa xác nhận được kết quả"
          description={error}
          closable
          onClose={() => setError("")}
          style={{ marginBottom: 24 }}
          role="alert"
        />
      )}
      {saved && (
        <Alert
          type="success"
          showIcon
          message={`Đã ${saved.amount > 0 ? "cộng" : "trừ"} ${formatMoney(
            Math.abs(saved.amount)
          )} ${saved.amount > 0 ? "vào" : "khỏi"} ví hoa hồng của ${
            saved.customer.name || `khách hàng #${saved.customer.id}`
          }`}
          description={`Mã giao dịch: ${saved.transactionId}`}
          style={{ marginBottom: 24 }}
          role="status"
        />
      )}

      <Card title="Cộng / trừ ví hoa hồng">
        <Form<FormValues>
          form={form}
          layout="vertical"
          onFinish={confirmSubmit}
          scrollToFirstError
          aria-busy={saving}
        >
          <Form.Item
            label="Khách hàng"
            required
            validateStatus={selectionError ? "error" : undefined}
            help={selectionError || undefined}
          >
            <Button
              onClick={() => setPickerOpen(true)}
              aria-label="Chọn khách hàng"
              disabled={saving}
            >
              {selectedCustomer ? "Đổi khách hàng" : "Chọn khách hàng"}
            </Button>
            {selectedCustomer && (
              <div style={{ marginTop: 12 }}>
                <Typography.Text strong>
                  {selectedCustomer.name ||
                    `Khách hàng #${selectedCustomer.id}`}
                </Typography.Text>
                <br />
                <Typography.Text type="secondary">
                  ID {selectedCustomer.id}
                  {selectedCustomer.phone ? ` · ${selectedCustomer.phone}` : ""}
                  {selectedCustomer.email ? ` · ${selectedCustomer.email}` : ""}
                </Typography.Text>
              </div>
            )}
          </Form.Item>

          <Form.Item
            name="amount"
            label="Số tiền điều chỉnh ví hoa hồng"
            extra="Số dương: cộng vào ví. Số âm: trừ khỏi ví. Mỗi thao tác tạo một giao dịch hoa hồng."
            rules={[
              { required: true, message: "Vui lòng nhập số tiền điều chỉnh" },
              {
                validator: (_, value) =>
                  value === undefined ||
                  (Number.isSafeInteger(value) && value !== 0)
                    ? Promise.resolve()
                    : Promise.reject(
                        new Error(
                          "Nhập số nguyên khác 0 trong giới hạn cho phép"
                        )
                      ),
              },
            ]}
          >
            <InputNumber
              disabled={saving}
              min={-Number.MAX_SAFE_INTEGER}
              max={Number.MAX_SAFE_INTEGER}
              precision={0}
              formatter={moneyFormatter}
              parser={moneyParser as any}
              placeholder="Ví dụ: 1.000.000 hoặc -1.000.000"
              onChange={(value) =>
                setEnteredAmount(typeof value === "number" ? value : null)
              }
              style={{ width: "100%" }}
            />
          </Form.Item>

          <Button
            type="primary"
            htmlType="submit"
            icon={
              enteredAmount !== null && enteredAmount < 0 ? (
                <MinusOutlined />
              ) : (
                <PlusOutlined />
              )
            }
            danger={enteredAmount !== null && enteredAmount < 0}
            loading={saving}
            disabled={saving}
          >
            {saving
              ? "Đang xử lý..."
              : enteredAmount !== null && enteredAmount < 0
              ? "Trừ hoa hồng"
              : "Cộng hoa hồng"}
          </Button>
        </Form>
      </Card>

      {selectedCustomer && (
        <Row gutter={[16, 16]} align="stretch" style={{ marginTop: 24 }}>
          <Col xs={24} xl={8}>
            <Card
              title={`Số dư ví hoa hồng · ${
                selectedCustomer.name || `ID ${selectedCustomer.id}`
              }`}
              style={{ height: "100%" }}
              extra={
                <Button
                  icon={<ReloadOutlined />}
                  aria-label="Tải lại số dư ví hoa hồng"
                  onClick={() => setBalanceRefresh((value) => value + 1)}
                  disabled={balanceLoading}
                />
              }
            >
              {balanceError && (
                <Alert
                  type="error"
                  showIcon
                  message={balanceError}
                  role="alert"
                />
              )}
              <div aria-busy={balanceLoading} role="status">
                <Statistic
                  title="Số dư khả dụng"
                  value={
                    balanceLoading || !balance ? "—" : balance.availableAmount
                  }
                  suffix={balanceLoading || !balance ? undefined : "đ"}
                  groupSeparator="."
                />
              </div>
            </Card>
          </Col>
          <Col xs={24} xl={16}>
            <Card
              title="Lịch sử giao dịch hoa hồng"
              style={{ height: "100%" }}
              extra={
                <Space>
                  <Button
                    icon={<DownloadOutlined />}
                    aria-label="Xuất Excel"
                    loading={exporting}
                    onClick={exportHistory}
                  >
                    Xuất Excel
                  </Button>
                  <Button
                    icon={<ReloadOutlined />}
                    aria-label="Tải lại lịch sử giao dịch"
                    onClick={() => setHistoryRefresh((value) => value + 1)}
                    disabled={historyLoading}
                  />
                </Space>
              }
            >
              {exportError && (
                <Alert
                  type="error"
                  showIcon
                  message={exportError}
                  style={{ marginBottom: 16 }}
                  role="alert"
                />
              )}
              {historyError && (
                <Alert
                  type="error"
                  showIcon
                  message={historyError}
                  style={{ marginBottom: 16 }}
                  role="alert"
                />
              )}
              <Table<TransactionItem>
                rowKey="id"
                columns={historyColumns}
                dataSource={transactions}
                loading={historyLoading}
                scroll={{ x: 850 }}
                locale={{
                  emptyText: historyError
                    ? "Không thể tải lịch sử giao dịch"
                    : "Chưa có giao dịch hoa hồng",
                }}
                pagination={{
                  current: historyPage,
                  pageSize: HISTORY_PAGE_SIZE,
                  total: historyTotal,
                  showSizeChanger: false,
                  showTotal: (total, range) =>
                    `${range[0]}–${range[1]} trên ${total} giao dịch`,
                }}
                onChange={(pagination) =>
                  setHistoryPage(pagination.current || 1)
                }
              />
            </Card>
          </Col>
        </Row>
      )}

      <CustomerPicker
        pageInfo={pageInfo}
        visible={pickerOpen}
        selectedCustomer={selectedCustomer}
        onSelect={(customer) => {
          setSelectedCustomer(customer);
          setSelectionError("");
          setPickerOpen(false);
          setBalance(null);
          setBalanceError("");
          setTransactions([]);
          setHistoryError("");
          setExportError("");
          setHistoryTotal(0);
          setHistoryPage(1);
          setBalanceRefresh((value) => value + 1);
          setHistoryRefresh((value) => value + 1);
          setSaved(null);
        }}
        onCancel={() => setPickerOpen(false)}
      />
    </div>
  );
}
